-- =============================================================================
-- 537 — LE CAHIER D'EXERCICES DE 1RE (partie 25)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 537 --niveau 1re --fichiers hlp.n1,hlp.n2,ingenierie-dd.n1 --suffixe 25 > supabase/contenu/537_exercices_1re_25.sql
--
-- 87 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   hlp.n1                  33 exercices · 11 chapitres
--   hlp.n2                  33 exercices · 11 chapitres
--   ingenierie-dd.n1        21 exercices · 7 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('27c289c8-0c4c-51ec-b1e2-bf84d2c41ae1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le délégué qui veut rouvrir le foyer","competence":"analyser-texte","situation":"Samir, délégué de classe, plaide devant le conseil des élèves pour qu’on rouvre le foyer. Tu repères comment sa parole agit sur ceux qui l’écoutent.","documents":[{"id":"disc","type":"texte","genre":"source","titre":"Le plaidoyer de Samir","blocs":["Chers camarades, depuis septembre, je suis votre délégué et j’ai rendu compte de chaque conseil de classe : vous pouvez me faire confiance.","Le foyer est fermé depuis deux mois, et 120 élèves y déjeunaient chaque semaine : sa fermeture coûte plus cher en retards qu’elle ne fait économiser.","Imaginez le désarroi des sixièmes, seuls dans le couloir, sans un endroit où s’asseoir. Rouvrons le foyer."],"source":"Discours imaginaire, écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui nomme un sentiment que Samir veut faire éprouver.","aide":"Cherche un nom de sentiment, pas un fait ni un chiffre.","type":"zone","document":"disc","multiple":false},{"enonce":"Range chaque phrase de Samir du côté du logos, de l’ethos ou du pathos.","aide":"Le logos avance une preuve, l’ethos soigne l’image de l’orateur, le pathos touche.","type":"categories","categories":[{"id":"c0","texte":"Logos"},{"id":"c1","texte":"Ethos"},{"id":"c2","texte":"Pathos"}],"items":[{"id":"i0","texte":"« Je suis votre délégué depuis septembre »"},{"id":"i1","texte":"« Vous pouvez me faire confiance »"},{"id":"i2","texte":"« 120 élèves y déjeunaient chaque semaine »"},{"id":"i3","texte":"« Imaginez le désarroi des sixièmes »"}]},{"enonce":"Remets dans l’ordre les étapes du discours de Samir.","aide":"Relis les trois paragraphes dans l’ordre : crédibilité, preuve, émotion, demande.","type":"ordre","items":[{"id":"a","texte":"Il formule sa demande : rouvrir le foyer"},{"id":"b","texte":"Il rappelle qu’il est le délégué et qu’on peut lui faire confiance"},{"id":"c","texte":"Il fait imaginer la scène des sixièmes dans le couloir"},{"id":"d","texte":"Il avance un fait chiffré sur le foyer"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m51"]},"explication":"Le mot est **désarroi** : Samir cherche à toucher la sensibilité de ses camarades, c’est le **pathos**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c2"}},"explication":"Le **logos** s’appuie sur un fait chiffré ; l’**ethos** est l’image que Samir donne de lui (délégué, digne de confiance) ; le **pathos** fait imaginer une scène triste."},{"cle":{"type":"ordre","ids":["b","d","c","a"]},"explication":"Samir **s’installe d’abord comme orateur fiable, avance sa preuve, touche ensuite, puis demande** : les trois moyens se succèdent avant la conclusion."}]$ex$::jsonb),
  ('27c289c8-0c4c-51ec-b1e2-bf84d2c41ae1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Convaincue, mais pas décidée","competence":"analyser-document","situation":"Lina doit réviser pour le brevet blanc. Deux conversations par messages, avec Hugo puis avec Tom, montrent deux façons d’agir sur elle.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages de Lina","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"},{"nom":"Tom","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Hugo","texte":"Ça sert à quoi de réviser 20 minutes par jour ?"},{"qui":"Lina","texte":"J’ai tout calculé : 20 minutes par jour, c’est 10 heures avant le brevet blanc. Je sais que ça suffit."},{"qui":"Hugo","texte":"Alors tu t’y mets ?"},{"qui":"Lina","texte":"Non… je sais qu’il faudrait, mais je n’y arrive pas."},{"qui":"Tom","texte":"Tout le monde a déjà l’appli, tu vas rater le truc du siècle !"},{"qui":"Lina","texte":"Bon, je la télécharge. Je ne sais même pas si elle marche."}]}],"questions":[{"enonce":"Au début de la conversation avec Hugo, dans quel état est Lina ?","aide":"Elle a la preuve que 20 minutes suffisent. Passe-t-elle à l’action ?","type":"choix","options":[{"id":"a","texte":"À la fois convaincue et persuadée"},{"id":"b","texte":"Convaincue sans être persuadée"},{"id":"c","texte":"Ni convaincue ni persuadée"},{"id":"d","texte":"Persuadée sans être convaincue"}],"multiple":false},{"enonce":"Touche le mot de Tom qui joue sur la peur de manquer quelque chose.","aide":"Cherche le verbe qui évoque une occasion perdue.","type":"zone","document":"sms","multiple":false},{"enonce":"À la fin, Lina télécharge l’appli. Complète sa situation.","aide":"Elle agit, mais elle n’a aucune preuve que l’appli marche.","type":"trous","segments":["Lina est ",0," sans être ",1,"."],"banque":["ruinée","convaincue","ravie","persuadée"]},{"enonce":"Associe chaque notion à son moyen ou à son risque.","aide":"Pense à Hugo (la preuve) puis à Tom (la peur).","type":"association","gauche":[{"id":"g0","texte":"Convaincre : les moyens"},{"id":"g1","texte":"Persuader : les moyens"},{"id":"g2","texte":"Convaincre : le risque"},{"id":"g3","texte":"Persuader : le risque"}],"droite":[{"id":"d0","texte":"Être juste et inaudible"},{"id":"d1","texte":"L’image, le rythme, l’exemple frappant"},{"id":"d2","texte":"Être efficace et faux"},{"id":"d3","texte":"La démonstration"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Lina est **convaincue sans être persuadée** : sa raison accepte le calcul, mais elle ne se résout pas à agir."},{"cle":{"type":"zone","ids":["m57"]},"explication":"Le mot est **rater** : Tom ne donne aucune preuve, il agit sur la sensibilité de Lina."},{"cle":{"type":"trous","trous":[["persuadee"],["convaincue"]]},"affichage":"persuadée · convaincue","explication":"Elle est **persuadée sans être convaincue** : l’émotion l’a emporté, sans preuve — c’est précisément le danger."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"**Convaincre** passe par la démonstration, au risque d’être juste et inaudible ; **persuader** passe par l’image et l’exemple frappant, au risque d’être efficace et faux."}]$ex$::jsonb),
  ('27c289c8-0c4c-51ec-b1e2-bf84d2c41ae1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le conférencier qui vend la méthode miracle","competence":"argumenter","situation":"Un conférencier imaginaire vend une méthode pour « tout retenir sans effort ». Tu démontes sa parole, puis tu la situes entre le philosophe et le sophiste.","documents":[{"id":"conf","type":"texte","genre":"source","titre":"Extrait de la conférence","blocs":["Je suis docteur en neurosciences et j’ai formé trois mille élèves. Qui, parmi vous, ne rêve pas de réussir sans effort ? Vous voulez retenir, vous voulez briller, vous voulez gagner : ma méthode est là. Elle est garantie à cent pour cent."],"source":"Texte imaginaire, écrit pour l’exercice"},{"id":"tab","type":"tableau","titre":"Le philosophe et le sophiste","colonnes":["","Le philosophe","Le sophiste"],"lignes":[["Ce qu’il cherche","La vérité","Avoir raison"],["Ce qu’il enseigne","À examiner","À l’emporter"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui sert à bâtir la crédibilité du conférencier.","aide":"Quel titre donne de l’autorité à celui qui parle ?","type":"zone","document":"conf","multiple":false},{"enonce":"Que fait la phrase « Qui, parmi vous, ne rêve pas de réussir sans effort ? »","aide":"L’orateur attend-il vraiment que quelqu’un lui réponde ?","type":"choix","options":[{"id":"a","texte":"Elle dit moins pour suggérer plus"},{"id":"b","texte":"Elle répète un mot en début de phrases"},{"id":"c","texte":"Elle rapproche deux termes contradictoires"},{"id":"d","texte":"Elle pose une question qui n’attend pas de réponse"}],"multiple":false},{"enonce":"Quel moyen aristotélicien ce discours laisse-t-il de côté ?","aide":"Cherche un chiffre vérifié ou un raisonnement qui enchaîne.","type":"choix","options":[{"id":"a","texte":"Le logos : aucune preuve ni aucun raisonnement"},{"id":"b","texte":"L’ethos : l’orateur ne dit rien de lui-même"},{"id":"c","texte":"Le pathos : rien n’y touche au désir"},{"id":"d","texte":"Aucun : les trois sont présents et équilibrés"}],"multiple":false},{"enonce":"D’après le tableau, de quel côté se place ce conférencier ?","aide":"Fait-il examiner sa méthode, ou cherche-t-il à ce qu’on l’adopte ?","type":"choix","options":[{"id":"a","texte":"D’aucun côté, car il ne cherche rien"},{"id":"b","texte":"Du côté du philosophe, qui fait examiner"},{"id":"c","texte":"Du côté du sophiste, qui cherche à l’emporter"},{"id":"d","texte":"Des deux côtés à la fois, selon les phrases"}],"multiple":false},{"enonce":"Dans le Gorgias, Platon compare cette façon de parler à une pratique. Complète sa formule.","aide":"Une pratique qui fait plaisir sans faire de bien.","type":"trous","segments":["La rhétorique est comme la ",0," : elle ",1," au lieu de soigner."],"banque":["flatte","médecine","cuisine","instruit"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"Le mot est **docteur** : il construit l’**ethos**, l’image d’un orateur compétent."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est une **question rhétorique** : elle ne cherche pas de réponse, elle installe une évidence et flatte le désir de l’auditoire."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est le **logos** : « garantie à cent pour cent » n’est pas une preuve. Le discours s’appuie sur l’ethos et le pathos, ce qui le rend suspect."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il est du côté du **sophiste** : il veut emporter l’adhésion, non faire examiner ce qu’il avance."},{"cle":{"type":"trous","trous":[["cuisine"],["flatte"]]},"affichage":"cuisine · flatte","explication":"Platon compare la rhétorique à la **cuisine** : elle **flatte** au lieu de soigner."}]$ex$::jsonb),
  ('dc33abee-1469-56af-9ba1-7ce5a63ab276'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois discours, trois lieux","competence":"analyser-document","situation":"Tu relèves trois prises de parole dans un journal imaginaire et tu les ranges selon les trois genres de la rhétorique.","documents":[{"id":"tab","type":"tableau","titre":"Trois prises de parole","colonnes":["Scène","Où ?","Ce que dit l’orateur"],"lignes":[["A","Au tribunal","« Mon client n’était pas sur les lieux ce soir-là. »"],["B","À l’assemblée du département","« Votons dès demain la construction de la piste cyclable. »"],["C","Pendant une cérémonie","« Honorons le courage de nos anciens. »"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case où l’orateur parle de l’avenir et d’une décision à prendre.","aide":"Cherche le verbe qui engage une décision future.","type":"zone","document":"tab","multiple":false},{"enonce":"Associe chaque scène à son genre rhétorique.","aide":"Tribunal, assemblée, cérémonie : un genre par lieu.","type":"association","gauche":[{"id":"g0","texte":"Scène A"},{"id":"g1","texte":"Scène B"},{"id":"g2","texte":"Scène C"}],"droite":[{"id":"d0","texte":"Délibératif"},{"id":"d1","texte":"Judiciaire"},{"id":"d2","texte":"Épidictique"}]},{"enonce":"Quelle fin vise le discours de la scène B ?","aide":"Le délibératif décide de ce qui sera bon pour la cité.","type":"choix","options":[{"id":"a","texte":"Le vrai"},{"id":"b","texte":"Le beau"},{"id":"c","texte":"Le juste"},{"id":"d","texte":"L’utile"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"C’est la scène B : « **Votons dès demain** » regarde l’avenir et cherche l’utile."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"A est **judiciaire** (le tribunal), B **délibératif** (l’assemblée), C **épidictique** (la cérémonie, on loue)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le genre délibératif porte sur l’avenir et vise l’**utile** ; le judiciaire vise le juste, l’épidictique le beau."}]$ex$::jsonb),
  ('dc33abee-1469-56af-9ba1-7ce5a63ab276'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le plaidoyer de Maître Roche","competence":"analyser-texte","situation":"Maître Roche défend un client accusé d’un vol. Quatre fragments de sa plaidoirie ont été mélangés ; tu retrouves comment un discours s’organise.","documents":[{"id":"plaid","type":"texte","genre":"source","titre":"Fragments d’une plaidoirie","blocs":["Pour finir : relâchez-le, car punir un innocent, c’est condamner la justice elle-même.","Messieurs les jurés, je sais l’émotion qui vous étreint, et je vous demande seulement de m’écouter avec attention.","Les faits, d’abord : le 12 mars, mon client quittait son travail à 18 heures, comme le prouve son badge.","Ensuite, les preuves : la caméra de la gare le montre à 18 h 40, à quinze kilomètres du lieu du vol."],"source":"Plaidoirie imaginaire, écrite pour l’exercice"}],"questions":[{"enonce":"Devant quels juges et pour quelle fin Maître Roche parle-t-il ?","aide":"Il défend un accusé devant des jurés, à propos d’un fait passé.","type":"choix","options":[{"id":"a","texte":"À l’assemblée, pour décider de l’utile"},{"id":"b","texte":"Au tribunal, pour établir ce qui est juste"},{"id":"c","texte":"À la télévision, pour distraire"},{"id":"d","texte":"En cérémonie, pour louer le beau"}],"multiple":false},{"enonce":"Remets dans l’ordre les parties de la plaidoirie.","aide":"Une plaidoirie s’ouvre en captant l’attention et se termine en concluant.","type":"ordre","items":[{"id":"a","texte":"« Messieurs les jurés, je sais l’émotion… »"},{"id":"b","texte":"« Ensuite, les preuves… »"},{"id":"c","texte":"« Pour finir : relâchez-le… »"},{"id":"d","texte":"« Les faits, d’abord… »"}]},{"enonce":"Touche les deux objets qui servent de preuves.","aide":"Un badge et une image de surveillance : cherche ce qui peut se vérifier.","type":"zone","document":"plaid","multiple":true},{"enonce":"Associe chaque partie de la rhétorique à ce que fait Maître Roche.","aide":"Les cinq parties vont de la recherche des arguments à la prononciation.","type":"association","gauche":[{"id":"g0","texte":"Invention"},{"id":"g1","texte":"Élocution"},{"id":"g2","texte":"Mémoire"},{"id":"g3","texte":"Action"}],"droite":[{"id":"d0","texte":"Il joue de la voix, du regard et du geste"},{"id":"d1","texte":"Il plaide sans lire ses notes"},{"id":"d2","texte":"Il choisit ses mots et ses figures"},{"id":"d3","texte":"Il cherche quelles preuves utiliser"}]}]}$ex$::jsonb,
