  ('efad6864-ff09-52b3-b67c-8d583918f0fb'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un Persan à Paris","competence":"analyser-texte","situation":"Une lettre imaginaire, à la manière des Lettres persanes, montre comment le regard d’un étranger rend visible ce qu’un Parisien ne voit plus.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Zélim à un ami resté à Ispahan","blocs":["Ici, chacun me demande avec un sourire poli : « Comment peut-on être Persan ? » Personne ne songe que je pourrais, moi, demander : comment peut-on être Parisien ?","Ces gens passent chaque matin une heure à poudrer leur perruque, et jugent barbare que nous nous couvrions la tête d’un turban."],"source":"Lettre imaginaire, écrite pour l’exercice, à la manière de Montesquieu (1721)"}],"questions":[{"enonce":"Touche le mot par lequel les Parisiens jugent ce qui n’est pas de leur usage.","aide":"Montaigne : « chacun appelle … ce qui n’est pas de son usage ».","type":"zone","document":"lettre","multiple":false},{"enonce":"Quel effet produit le regard de Zélim sur le lecteur parisien ?","aide":"Pense à la perruque poudrée, que le Parisien ne remarque plus.","type":"choix","options":[{"id":"a","texte":"Il le persuade que la Perse vaut mieux que la France"},{"id":"b","texte":"Il lui prouve que toutes les coutumes se valent"},{"id":"c","texte":"Il lui apprend la géographie de l’Orient"},{"id":"d","texte":"Il lui fait voir comme étrange ce qu’il trouvait naturel"}],"multiple":false},{"enonce":"Remets dans l’ordre le mécanisme du regard étranger.","aide":"On part de l’arrivée de l’étranger et on termine sur le lecteur.","type":"ordre","items":[{"id":"a","texte":"Il la décrit avec naïveté"},{"id":"b","texte":"Il remarque une coutume que plus personne ne remarque"},{"id":"c","texte":"Le lecteur voit sa propre coutume comme une coutume parmi d’autres"},{"id":"d","texte":"Un étranger arrive dans une société"}]},{"enonce":"Complète la phrase du cours.","aide":"C’est celui qui vit dans l’évidence.","type":"trous","segments":["Un Persan à Paris rend visible ce qu’un ",0," ne voit plus."],"banque":["Persan","savant","roi","Parisien"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m37"]},"explication":"Le mot est **barbare** : c’est le jugement que Montaigne dénonce."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le regard étranger **dénaturalise** les évidences : une coutume cesse de paraître naturelle. Il ne dit pas que « tout se vaut »."},{"cle":{"type":"ordre","ids":["d","b","a","c"]},"explication":"L’étranger **arrive, remarque, décrit naïvement**, et le lecteur **se voit lui-même** : décrire le monde, c’est aussi se décrire."},{"cle":{"type":"trous","trous":[["parisien"]]},"affichage":"Parisien","explication":"Il rend visible ce qu’un **Parisien** ne voit plus, parce que c’est devenu une habitude."}]$ex$::jsonb),
  ('efad6864-ff09-52b3-b67c-8d583918f0fb'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Aurelia ou Lumen ?","competence":"analyser-document","situation":"Deux cités imaginaires sont décrites dans un guide de voyage fictif. Tu les classes, et tu retrouves la fonction de chaque genre.","documents":[{"id":"cites","type":"texte","genre":"article","titre":"Deux cités imaginaires","blocs":["À Aurelia, chacun travaille six heures par jour et toutes les décisions se débattent en public. Nul n’y a faim ni froid.","À Lumen, le bonheur est obligatoire : des écrans surveillent chaque foyer, et celui qui doute est conduit au centre de rééducation."],"source":"Guide imaginaire, écrit pour l’exercice"},{"id":"gen","type":"tableau","titre":"Utopie et dystopie","colonnes":["Genre","Ce qu’il décrit","Ce qu’il vise"],"lignes":[["Utopie","Une société parfaite, ailleurs","Critiquer la sienne par contraste"],["Dystopie","Une société parfaite devenue cauchemar","Avertir"]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque trait du côté de l’utopie ou de la dystopie.","aide":"Aurelia est la cité parfaite ; Lumen est la cité parfaite devenue cauchemar.","type":"categories","categories":[{"id":"c0","texte":"Utopie"},{"id":"c1","texte":"Dystopie"}],"items":[{"id":"i0","texte":"Le bonheur est obligatoire"},{"id":"i1","texte":"Chacun travaille six heures par jour"},{"id":"i2","texte":"Toutes les décisions se débattent en public"},{"id":"i3","texte":"Des écrans surveillent chaque foyer"}]},{"enonce":"Touche le mot qui montre que le bonheur est imposé.","aide":"Un bonheur qu’on ne peut pas refuser.","type":"zone","document":"cites","multiple":false},{"enonce":"D’après le tableau, à quoi sert Aurelia pour l’auteur du guide ?","aide":"Le tableau dit ce que vise l’utopie.","type":"choix","options":[{"id":"a","texte":"À critiquer sa propre société par contraste"},{"id":"b","texte":"À prédire l’avenir exact de la société"},{"id":"c","texte":"À avertir qu’un régime idéal tourne mal"},{"id":"d","texte":"À décrire un pays existant et visité"}],"multiple":false},{"enonce":"Thomas More forge le mot en 1516, à partir du grec ou-topos. Complète sa signification.","aide":"Un lieu qui n’existe nulle part.","type":"trous","segments":["« Utopie » signifie le lieu de ",0," part."],"banque":["toute","autre","nulle","bonne"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Les deux premiers traits décrivent **Aurelia** (utopie) ; l’obligation du bonheur et la surveillance sont ceux de **Lumen** (dystopie)."},{"cle":{"type":"zone","ids":["m28"]},"explication":"Le mot est **obligatoire** : un bonheur imposé est un cauchemar, c’est la marque de la dystopie."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’utopie décrit une société parfaite, ailleurs, pour **critiquer la sienne par contraste** ; c’est la dystopie qui avertit."},{"cle":{"type":"trous","trous":[["nulle"]]},"affichage":"nulle","explication":"Ou-topos veut dire le lieu de **nulle** part : une société parfaite qui n’existe nulle part."}]$ex$::jsonb),
  ('68971180-7810-5c37-ade6-837443d664e7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois extraits, trois fonctions","competence":"analyser-texte","situation":"Le club de théâtre du lycée prépare trois prises de parole. Chacune sert une fonction différente du discours : tu retrouves laquelle.","documents":[{"id":"ext","type":"texte","genre":"source","titre":"Trois extraits","blocs":["Extrait A. Pour passer le brevet, il faut obtenir 10 sur 20 de moyenne : voici comment on calcule cette moyenne.","Extrait B. Ce matin d’été, la cour du collège ressemblait à une ruche dorée où chacun butinait sa part de soleil.","Extrait C. Vous qui m’écoutez, vous avez vu ses larmes : n’abandonnez pas cet enfant !"],"source":"Extraits imaginaires, écrits pour l’exercice"}],"questions":[{"enonce":"Associe chaque extrait à la fonction du discours qu’il sert.","aide":"Un extrait explique, un autre fait une image, le dernier touche.","type":"association","gauche":[{"id":"g0","texte":"Extrait A"},{"id":"g1","texte":"Extrait B"},{"id":"g2","texte":"Extrait C"}],"droite":[{"id":"d0","texte":"Émouvoir"},{"id":"d1","texte":"Plaire"},{"id":"d2","texte":"Instruire"}]},{"enonce":"Touche les deux mots qui font vivre l’image du collège comme une ruche.","aide":"Un lieu et une action d’abeilles.","type":"zone","document":"ext","multiple":true},{"enonce":"L’extrait C est le plus fort sur le plan des sentiments. Complète le nom de son style.","aide":"Le simple instruit, le tempéré plaît.","type":"trous","segments":["Pour émouvoir, on emploie le style ",0,"."],"banque":["tempéré","sublime","familier","simple"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"A **instruit** (il explique un calcul), B **plaît** (il fait une image), C **émeut** (il en appelle aux larmes) : les trois fonctions de Cicéron."},{"cle":{"type":"zone","ids":["m33","m37"]},"explication":"**Ruche** et **butinait** filent l’image : le collège devient une ruche. C’est ce qui fait **plaire** l’extrait B."},{"cle":{"type":"trous","trous":[["sublime"]]},"affichage":"sublime","explication":"La fonction **émouvoir** (*movere*) correspond au style **sublime**."}]$ex$::jsonb),
