   $ex${"titre":"Le carnet de figures","competence":"comprendre-langue","situation":"Dans son carnet, Mathis a noté six phrases entendues cette semaine. Tu les classes par familles de figures et tu expliques leur effet.","documents":[{"id":"car","type":"tableau","titre":"Le carnet de Mathis","colonnes":["N°","Phrase relevée"],"lignes":[["1","Le temps est un fleuve qui emporte nos projets"],["2","Jamais de pause, jamais de retard, jamais de doute"],["3","Ce n’est pas un mauvais résultat"],["4","Un silence assourdissant"],["5","Il faut manger pour vivre, non vivre pour manger"],["6","J’ai attendu mille ans devant ce guichet"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la phrase qui rapproche deux termes contradictoires.","aide":"Un silence peut-il être assourdissant ? Cherche l’alliance de contraires.","type":"zone","document":"car","multiple":false},{"enonce":"Range chaque phrase dans sa famille de figures.","aide":"Une famille rend sensible, une martèle, une oppose, une dit moins.","type":"categories","categories":[{"id":"c0","texte":"Analogie"},{"id":"c1","texte":"Insistance"},{"id":"c2","texte":"Opposition"},{"id":"c3","texte":"Atténuation"}],"items":[{"id":"i0","texte":"Un silence assourdissant"},{"id":"i1","texte":"J’ai attendu mille ans devant ce guichet"},{"id":"i2","texte":"Le temps est un fleuve qui emporte nos projets"},{"id":"i3","texte":"Jamais de pause, jamais de retard, jamais de doute"},{"id":"i4","texte":"Il faut manger pour vivre, non vivre pour manger"},{"id":"i5","texte":"Ce n’est pas un mauvais résultat"}]},{"enonce":"Quel est l’effet de la phrase 3, « Ce n’est pas un mauvais résultat » ?","aide":"Le locuteur emploie une négation pour dire quelque chose de positif.","type":"choix","options":[{"id":"a","texte":"Elle rend sensible une idée abstraite par une image"},{"id":"b","texte":"Elle dit moins pour suggérer plus : le résultat est bon"},{"id":"c","texte":"Elle amplifie le résultat en le grossissant"},{"id":"d","texte":"Elle martèle une idée en la répétant"}],"multiple":false},{"enonce":"Associe chaque figure à ce qu’elle fait.","aide":"Reprends les quatre familles : insistance, analogie, atténuation, opposition.","type":"association","gauche":[{"id":"g0","texte":"Anaphore"},{"id":"g1","texte":"Métaphore"},{"id":"g2","texte":"Litote"},{"id":"g3","texte":"Antithèse"}],"droite":[{"id":"d0","texte":"Rendre sensible l’abstrait"},{"id":"d1","texte":"Dire moins pour suggérer plus"},{"id":"d2","texte":"Marteler et amplifier"},{"id":"d3","texte":"Structurer la pensée en tensions"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"C’est **« Un silence assourdissant »** : un **oxymore**, qui rapproche deux termes contradictoires."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c1","i4":"c2","i5":"c3"}},"explication":"Métaphore : **analogie** ; anaphore et hyperbole : **insistance** ; oxymore et chiasme : **opposition** ; litote : **atténuation**."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est une **litote** : en niant le contraire, elle **dit moins pour suggérer plus**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"L’**anaphore** martèle, la **métaphore** rend sensible l’abstrait, la **litote** dit moins, l’**antithèse** structure la pensée en tensions."}]$ex$::jsonb),
