  ('3768bdcc-05dc-5b61-bdad-458d2c6621b6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois publications à lire de près","competence":"analyser-texte","situation":"Sur son téléphone, Inès voit passer trois publications. Chacune s’appuie sur un ressort différent de la rhétorique d’Aristote.","documents":[{"id":"posts","type":"texte","genre":"article","titre":"Trois publications imaginaires","blocs":["« INCROYABLE ! Ce que les profs vous cachent sur le brevet ! Partagez avant qu’on supprime ce post. »","« Moi, je vous parle vrai : je suis un élève comme vous et je ne vous vendrai jamais rien. »","« Selon un sondage mené dans un lycée imaginaire, un élève sur deux dort moins de sept heures avant un contrôle. Voici les chiffres. »"],"source":"Publications imaginaires, écrites pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui cherche à provoquer une réaction immédiate.","aide":"Cherche le mot en majuscules.","type":"zone","document":"posts","multiple":false},{"enonce":"Associe chaque publication à son ressort.","aide":"Une publication choque, une rassure, une chiffre.","type":"association","gauche":[{"id":"g0","texte":"Publication 1"},{"id":"g1","texte":"Publication 2"},{"id":"g2","texte":"Publication 3"}],"droite":[{"id":"d0","texte":"Ethos : l’authenticité mise en scène"},{"id":"d1","texte":"Logos : des chiffres"},{"id":"d2","texte":"Pathos : l’indignation"}]},{"enonce":"Complète la loi des réseaux.","aide":"La visibilité algorithmique récompense ce qui fait réagir.","type":"trous","segments":["Sur les réseaux, ce qui circule est ce qui suscite le plus de ",0,"."],"banque":["réactions","pages","preuves","années"]}]}$ex$::jsonb,
