  ('3768bdcc-05dc-5b61-bdad-458d2c6621b6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La phrase répétée et le boulanger","competence":"analyser-document","situation":"Deux documents imaginaires, un tableau de déclarations et un discours, montrent comment la parole politique s’adapte au monde des médias.","documents":[{"id":"porte","type":"tableau","titre":"Trois porte-parole, la même phrase","colonnes":["Moment","Porte-parole","Phrase prononcée"],"lignes":[["Matin","À la radio","« Nous prenons nos responsabilités. »"],["Midi","Au journal télévisé","« Nous prenons nos responsabilités. »"],["Soir","Sur un plateau","« Nous prenons nos responsabilités. »"]],"enteteLignes":true},{"id":"disc","type":"texte","genre":"source","titre":"Extrait d’un discours","blocs":["Parlons de Karim, boulanger à Ambert. Chaque nuit à trois heures, il pétrit. Aujourd’hui, sa boulangerie ferme. Cet homme, c’est vous, c’est nous."],"source":"Discours imaginaire, écrit pour l’exercice"}],"questions":[{"enonce":"Pourquoi la même phrase revient-elle trois fois dans la journée ?","aide":"Une formule préparée à l’avance et répétée partout.","type":"choix","options":[{"id":"a","texte":"C’est un élément de langage répété jusqu’à s’imposer"},{"id":"b","texte":"C’est un mème qui joue sur la connivence des internautes"},{"id":"c","texte":"C’est une litote qui dit moins pour suggérer plus"},{"id":"d","texte":"C’est une petite phrase faite pour une seule reprise"}],"multiple":false},{"enonce":"Touche le nom qui incarne l’argument dans le discours.","aide":"Cherche le prénom autour duquel le récit est construit.","type":"zone","document":"disc","multiple":false},{"enonce":"Associe chaque nouvelle figure à son fonctionnement.","aide":"Reprends les quatre figures du cours.","type":"association","gauche":[{"id":"g0","texte":"Élément de langage"},{"id":"g1","texte":"Petite phrase"},{"id":"g2","texte":"Storytelling"},{"id":"g3","texte":"Mème"}],"droite":[{"id":"d0","texte":"Une formule conçue pour être extraite et reprise"},{"id":"d1","texte":"Un récit incarné à la place de l’argument"},{"id":"d2","texte":"Un argument condensé en image, par connivence"},{"id":"d3","texte":"Une formule répétée jusqu’à s’imposer"}]},{"enonce":"Complète la phrase du cours sur le storytelling.","aide":"Karim est un récit, pas une démonstration.","type":"trous","segments":["Le storytelling remplace l’",0," par un ",1," incarné."],"banque":["récit","slogan","argument","chiffre"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"C’est un **élément de langage** : une formule préparée et répétée jusqu’à s’imposer comme une évidence."},{"cle":{"type":"zone","ids":["m2"]},"explication":"Le prénom est **Karim** : le discours remplace l’argument par un récit incarné."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"L’**élément de langage** se répète, la **petite phrase** s’extrait, le **storytelling** raconte, le **mème** condense par connivence."},{"cle":{"type":"trous","trous":[["argument"],["recit"]]},"affichage":"argument · récit","explication":"Il remplace l’**argument** par un **récit** incarné : plus mémorable, plus difficile à réfuter."}]$ex$::jsonb),
  ('3768bdcc-05dc-5b61-bdad-458d2c6621b6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une alerte sur l’eau du robinet","competence":"argumenter","situation":"Un message alarmiste circule dans la classe de Léa. Elle et Mehdi réagissent. Tu appliques les réflexes de la lecture critique.","documents":[{"id":"alerte","type":"texte","genre":"article","titre":"Le message qui circule","blocs":["URGENT. Selon un expert dont nous taisons le nom, l’eau du robinet rendrait malade un Français sur trois. Les autorités nous mentent ! Imaginez vos enfants, empoisonnés chaque matin. Partagez avant qu’on nous censure."],"source":"Message imaginaire, écrit pour l’exercice"},{"id":"echange","type":"dialogue","modele":"sms","titre":"La réaction de Léa et Mehdi","participants":[{"nom":"Mehdi","emoji":"👦","cote":"gauche"},{"nom":"Léa","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Mehdi","texte":"Tu as vu ? Un Français sur trois malade, c’est affreux, j’ai déjà partagé."},{"qui":"Léa","texte":"Qui a écrit ça ? Je ne vois aucune source."}]}],"questions":[{"enonce":"Touche le mot qui invoque une autorité sans la nommer.","aide":"Quel personnage non identifié est censé rendre le propos crédible ?","type":"zone","document":"alerte","multiple":false},{"enonce":"Range chaque passage du message selon ce qu’il fait.","aide":"Un chiffre se vérifie ; une accusation se prouve ; une scène touche ; un expert « garantit ».","type":"categories","categories":[{"id":"c0","texte":"Fait vérifiable"},{"id":"c1","texte":"Opinion"},{"id":"c2","texte":"Appel à l’émotion"},{"id":"c3","texte":"Argument d’autorité"}],"items":[{"id":"i0","texte":"Imaginez vos enfants, empoisonnés chaque matin"},{"id":"i1","texte":"Un Français sur trois serait malade"},{"id":"i2","texte":"Selon un expert dont nous taisons le nom"},{"id":"i3","texte":"Les autorités nous mentent"}]},{"enonce":"Quel réflexe critique Léa applique-t-elle en premier ?","aide":"Elle demande qui a écrit le message.","type":"choix","options":[{"id":"a","texte":"Repérer l’argument d’autorité"},{"id":"b","texte":"Distinguer le fait de l’opinion"},{"id":"c","texte":"Identifier la source"},{"id":"d","texte":"Repérer l’appel à l’émotion"}],"multiple":false},{"enonce":"Associe chaque réflexe critique à la question à poser.","aide":"Chaque réflexe a sa question dans le cours.","type":"association","gauche":[{"id":"g0","texte":"Identifier la source"},{"id":"g1","texte":"Distinguer le fait de l’opinion"},{"id":"g2","texte":"Repérer l’appel à l’émotion"},{"id":"g3","texte":"Repérer l’argument d’autorité"}],"droite":[{"id":"d0","texte":"Qui parle, et d’où ?"},{"id":"d1","texte":"Que veut-on me faire ressentir ?"},{"id":"d2","texte":"A-t-on examiné le propos, ou seulement son auteur ?"},{"id":"d3","texte":"Est-ce vérifiable ?"}]},{"enonce":"Complète la conclusion du cours.","aide":"Le verbe est inhabituel : on laisse les mots parler à votre place.","type":"trous","segments":["Savoir analyser un discours, c’est ne pas être ",0," par ce qu’on écoute."],"banque":["ennuyé","payé","parlé","flatté"]}]}$ex$::jsonb,
