   $ex${"titre":"Deux sujets, deux exercices","competence":"analyser-document","situation":"Au début de l’épreuve de HLP, Nora lit deux sujets. Avant d’écrire, elle doit comprendre quel exercice chacun demande.","documents":[{"id":"sujets","type":"texte","genre":"consigne","titre":"Les deux sujets","blocs":["**Sujet A.** Vous proposerez une interprétation littéraire de cette phrase : « Chacun appelle barbarie ce qui n’est pas de son usage. »","**Sujet B.** Une parole efficace est-elle une parole vraie ?"],"source":"Sujets imaginés pour l’exercice ; phrase de Montaigne, *Essais*, I, 31"}],"questions":[{"enonce":"Associe chaque sujet à l’exercice qu’il demande.","aide":"Un sujet part d’un texte, l’autre d’une question.","type":"association","gauche":[{"id":"g0","texte":"Sujet A"},{"id":"g1","texte":"Sujet B"}],"droite":[{"id":"d0","texte":"Essai philosophique"},{"id":"d1","texte":"Interprétation littéraire"}]},{"enonce":"Range chaque geste dans l’exercice qui le demande.","aide":"L’un travaille le texte, l’autre travaille la question.","type":"categories","categories":[{"id":"c0","texte":"Interprétation littéraire"},{"id":"c1","texte":"Essai philosophique"}],"items":[{"id":"i0","texte":"Montrer comment la forme produit le sens"},{"id":"i1","texte":"Problématiser la question"},{"id":"i2","texte":"Repérer le mouvement du texte"},{"id":"i3","texte":"Accepter l’objection"},{"id":"i4","texte":"Convoquer des exemples précis et des références"},{"id":"i5","texte":"Relever les procédés : lexique, syntaxe, images"}]},{"enonce":"Pour le sujet A, laquelle de ces conduites est un contresens ?","aide":"Le contresens de l’interprétation est le même que celui d’une paraphrase.","type":"choix","options":[{"id":"a","texte":"Citer le mot de la phrase qui appuie une idée"},{"id":"b","texte":"Chercher comment la forme produit le sens"},{"id":"c","texte":"Repérer la situation d’énonciation de la phrase"},{"id":"d","texte":"Raconter le texte au lieu de l’interpréter"}],"multiple":false}]}$