   $ex${"titre":"Le mot qui résiste","competence":"analyser-texte","situation":"Tu prépares l’interprétation littéraire des derniers vers d’un célèbre poème de Rimbaud. Le tableau de méthode t’aide à ne pas rester au niveau de l’affirmation générale.","documents":[{"id":"poeme","type":"texte","genre":"poeme","titre":"Le Dormeur du val (fin du poème)","blocs":["Les parfums ne font pas frissonner sa narine ;","Il dort dans le soleil, la main sur sa poitrine,","Tranquille. Il a deux trous rouges au côté droit."],"auteur":"Arthur Rimbaud"},{"id":"meth","type":"tableau","titre":"La méthode de travail","colonnes":["Le geste","Ce qu’il évite"],"lignes":[["Lire crayon en main","Relire trois fois sans rien retenir"],["Noter les mots qui résistent","Passer à côté de ce qui fait l’intérêt du texte"],["Formuler une question, pas un thème","Un plan qui juxtapose au lieu de progresser"]],"enteteLignes":true}],"questions":[{"enonce":"Selon le geste « noter les mots qui résistent », touche le mot qui détonne avec l’idée d’un sommeil paisible.","aide":"Cherche le mot qui annonce une blessure.","type":"zone","document":"poeme","multiple":false},{"enonce":"Remets dans l’ordre le mouvement de ces vers.","aide":"Suis le texte vers par vers, de haut en bas.","type":"ordre","items":[{"id":"a","texte":"Un seul mot, « Tranquille », ralentit la lecture"},{"id":"b","texte":"Les derniers mots révèlent les blessures"},{"id":"c","texte":"Le soldat paraît dormir, indifférent aux parfums"},{"id":"d","texte":"Il repose au soleil, la main sur la poitrine"}]},{"enonce":"Range chaque phrase selon sa valeur dans une copie.","aide":"Une interprétation s’appuie sur un mot et dit ce que la forme produit.","type":"categories","categories":[{"id":"c0","texte":"Paraphrase"},{"id":"c1","texte":"Affirmation sans preuve"},{"id":"c2","texte":"Interprétation"}],"items":[{"id":"i0","texte":"« Tranquille » est isolé, juste avant « trous » : la douceur se brise"},{"id":"i1","texte":"Le poète parle d’un jeune soldat endormi"},{"id":"i2","texte":"Un soldat est étendu et il a deux blessures"},{"id":"i3","texte":"Ce poème est très triste"}]},{"enonce":"Complète le principe du cours.","aide":"On attend du texte lui-même qu’il fournisse la preuve.","type":"trous","segments":["Une interprétation qui pourrait s’appliquer à n’importe quel autre texte n’est pas une ",0,"."],"banque":["citation","paraphrase","interprétation","introduction"]}]}$ex$::jsonb,
