  ('437f1d44-1389-5837-a346-3a7f1177e83b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Mythe, fable, légende ou conte ?","competence":"analyser-document","situation":"Quatre récits sont rangés dans un tableau pour l’atelier de lecture du CDI. Tu retrouves la nature de chacun.","documents":[{"id":"recits","type":"tableau","titre":"Quatre récits","colonnes":["Récit","Résumé"],"lignes":[["Récit A","Un renard flatte un corbeau pour lui prendre son fromage. À la fin, une morale écrite : « Tout flatteur vit aux dépens de celui qui l’écoute. »"],["Récit B","Un titan dérobe le feu aux dieux pour le donner aux hommes ; Zeus le punit. Nul ne sait qui a raconté cette histoire le premier."],["Récit C","À Roncevaux, en 778, l’arrière-garde de Charlemagne est écrasée ; la tradition raconte que le chevalier Roland sonna de l’olifant."],["Récit D","Il était une fois une princesse qui parlait aux grenouilles ; personne ne demande si c’est vrai."]],"enteteLignes":true,"source":"Résumés rédigés pour l’exercice ; morale d’après La Fontaine, *Le Corbeau et le Renard*"}],"questions":[{"enonce":"Associe chaque récit à sa nature.","aide":"Cherche la morale, l’origine sans auteur, le lieu historique, le « il était une fois ».","type":"association","gauche":[{"id":"g0","texte":"Récit A"},{"id":"g1","texte":"Récit B"},{"id":"g2","texte":"Récit C"},{"id":"g3","texte":"Récit D"}],"droite":[{"id":"d0","texte":"Conte"},{"id":"d1","texte":"Mythe"},{"id":"d2","texte":"Légende"},{"id":"d3","texte":"Fable"}]},{"enonce":"Touche la case qui donne une leçon morale explicite.","aide":"Cherche la phrase qui tire une conclusion pour le lecteur.","type":"zone","document":"recits","multiple":false},{"enonce":"D’où le récit B tient-il son autorité ?","aide":"Le résumé dit que personne ne sait qui l’a raconté en premier.","type":"choix","options":[{"id":"a","texte":"De la morale que son auteur en tire"},{"id":"b","texte":"De ce qu’il est reçu et transmis"},{"id":"c","texte":"De la date précise où il fut écrit"},{"id":"d","texte":"De ses preuves, qu’on peut vérifier"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"A est une **fable** (morale explicite), B un **mythe** (sans auteur ni preuve), C une **légende** (lieu et personnage historiques), D un **conte** (personne n’attend qu’il soit vrai)."},{"cle":{"type":"zone","ids":["r0c1"]},"explication":"C’est le récit A : « **Tout flatteur vit aux dépens de celui qui l’écoute** » est une morale explicite, la marque de la **fable**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Un mythe n’a **ni preuve ni auteur** : son autorité tient à ce qu’il est **reçu** et transmis."}]$ex$::jsonb),
