   $ex${"titre":"La dispute d’Athéna et de Poséidon","competence":"analyser-texte","situation":"Pour un exposé sur Athènes, Zoé lit un récit grec adapté. Elle cherche ce que le mythe explique, fonde ou justifie.","documents":[{"id":"mythe","type":"texte","genre":"recit","titre":"Le nom d’Athènes","blocs":["Athéna et Poséidon se disputent la protection de la cité. Poséidon frappe le rocher de l’Acropole et fait jaillir une source salée ; Athéna fait pousser un olivier.","Les Athéniens choisissent l’olivier, et la ville prend le nom d’Athènes."],"source":"Récit adapté de la tradition grecque"},{"id":"fct","type":"tableau","titre":"Les trois fonctions du mythe","colonnes":["La fonction","Ce qu’elle fait"],"lignes":[["Expliquer","Ce que l’on ne sait pas"],["Fonder","Une communauté"],["Justifier","Un ordre social"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que le récit explique d’où vient le nom de la cité.","aide":"Cherche ce que reçoit la ville à la fin du récit.","type":"zone","document":"mythe","multiple":false},{"enonce":"Range chaque exemple dans la fonction du mythe qu’il illustre.","aide":"Un mythe explique une énigme, fonde une ville ou justifie une règle sociale.","type":"categories","categories":[{"id":"c0","texte":"Expliquer"},{"id":"c1","texte":"Fonder"},{"id":"c2","texte":"Justifier"}],"items":[{"id":"i0","texte":"La Genèse et le travail"},{"id":"i1","texte":"D’où vient le feu"},{"id":"i2","texte":"Pourquoi il y a des saisons"},{"id":"i3","texte":"Romulus pour Rome"},{"id":"i4","texte":"La dispute d’Athéna et de Poséidon pour Athènes"}]},{"enonce":"Quelle fonction ce récit athénien remplit-il avant tout ?","aide":"Le mythe donne à la cité son nom et son origine commune.","type":"choix","options":[{"id":"a","texte":"Justifier une hiérarchie entre citoyens et esclaves"},{"id":"b","texte":"Fonder la communauté autour d’un récit d’origine partagé"},{"id":"c","texte":"Démontrer scientifiquement l’origine de l’olivier"},{"id":"d","texte":"Apprendre une leçon morale explicite aux enfants"}],"multiple":false},{"enonce":"Complète la phrase du cours sur le mythe.","aide":"Il n’a pas besoin de preuve.","type":"trous","segments":["Le mythe ne se discute pas : il se ",0,"."],"banque":["corrige","vérifie","raconte","démontre"]}]}$ex$::jsonb,
