   $ex${"titre":"Le dimanche « depuis toujours »","competence":"analyser-document","situation":"Une publicité imaginaire raconte comment « se passe » le dimanche. Avec le regard de Roland Barthes, tu y reconnais un mythe d’aujourd’hui.","documents":[{"id":"pub","type":"texte","genre":"article","titre":"Publicité d’une marque fictive","blocs":["Depuis toujours, le dimanche, la famille se retrouve autour du poulet rôti. C’est naturel, c’est la France. Offrez à vos enfants le vrai dimanche."],"source":"Publicité imaginaire, écrite pour l’exercice"},{"id":"mg","type":"tableau","titre":"Muthos et logos","colonnes":["Le terme grec","Ce qu’il désigne"],"lignes":[["Muthos","Le récit reçu"],["Logos","Le discours qui rend raison"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui fait passer une habitude pour une évidence de tous les temps.","aide":"Cherche l’adverbe qui nie toute origine historique.","type":"zone","document":"pub","multiple":false},{"enonce":"Range chaque phrase.","aide":"Une phrase se donne pour allant de soi, l’autre peut être contrôlée.","type":"categories","categories":[{"id":"c0","texte":"Évidence naturelle (mythe)"},{"id":"c1","texte":"Affirmation vérifiable"}],"items":[{"id":"i0","texte":"Le prix du poulet a augmenté de 10 % en un an, selon cette enquête"},{"id":"i1","texte":"Cette marque a vendu 2 millions de poulets en 2024, selon ses comptes"},{"id":"i2","texte":"Le café du matin est la tradition de la France entière"},{"id":"i3","texte":"Une vraie famille mange toujours un poulet rôti le dimanche"}]},{"enonce":"D’après le tableau et le cours, que fait Platon du mythe ?","aide":"Platon raconte la caverne, l’attelage ailé, le mythe d’Er.","type":"choix","options":[{"id":"a","texte":"Il le rejette totalement au nom du logos"},{"id":"b","texte":"Il le raconte pour démontrer une conclusion"},{"id":"c","texte":"Il l’oppose au logos sans jamais en raconter"},{"id":"d","texte":"Il y recourt quand l’argument ne suffit plus"}],"multiple":false},{"enonce":"Complète la phrase du cours.","aide":"Ce qu’on ne songe pas à discuter.","type":"trous","segments":["Reconnaître un mythe contemporain, c’est repérer ce qui se donne pour ",0,"."],"banque":["nouveau","allant de soi","amusant","prouvé"]},{"enonce":"Remets dans l’ordre les étapes de la lecture d’un mythe contemporain.","aide":"On lit d’abord, on soupçonne ensuite, on remonte, on discute.","type":"ordre","items":[{"id":"a","texte":"Repérer le texte ou l’image qui parle"},{"id":"b","texte":"Remettre l’évidence en discussion"},{"id":"c","texte":"Repérer ce qui se donne pour allant de soi"},{"id":"d","texte":"Retrouver la construction historique derrière l’évidence"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"Le mot est **toujours** : il transforme une construction historique en **évidence naturelle**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Les deux premières **se donnent pour allant de soi** (mythe contemporain) ; les deux autres contiennent un chiffre que l’on peut **vérifier**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Platon, qui naît **contre** le mythe, y recourt pourtant : le mythe **prolonge** le raisonnement au lieu de s’y opposer."},{"cle":{"type":"trous","trous":[["allant de soi"]]},"affichage":"allant de soi","explication":"Reconnaître un mythe contemporain, c’est repérer ce qui se donne pour **allant de soi**."},{"cle":{"type":"ordre","ids":["a","c","d","b"]},"explication":"On **lit**, on repère l’**évidence**, on retrouve la **construction historique**, puis on **remet en discussion**."}]$ex$::jsonb),
