   $ex${"titre":"Pourquoi les écoute-t-on ?","competence":"analyser-document","situation":"Quatre personnes parlent en public dans un journal imaginaire. Tu retrouves ce qui donne du poids à leur parole.","documents":[{"id":"voix","type":"tableau","titre":"Quatre voix","colonnes":["Qui parle","Ce qui fait écouter"],"lignes":[["Un juge","Il occupe la fonction de juger"],["Une médecin","Elle a étudié la médecine pendant des années"],["Un militant qui vit comme il parle","Sa vie garantit sa parole"],["Un chanteur très suivi","Il séduit par sa seule présence"]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque voix à son type d’autorité.","aide":"Fonction, savoir, exemplarité, présence.","type":"association","gauche":[{"id":"g0","texte":"Un juge"},{"id":"g1","texte":"Une médecin"},{"id":"g2","texte":"Un militant qui vit comme il parle"},{"id":"g3","texte":"Un chanteur très suivi"}],"droite":[{"id":"d0","texte":"Autorité de compétence"},{"id":"d1","texte":"Autorité morale"},{"id":"d2","texte":"Autorité charismatique"},{"id":"d3","texte":"Autorité institutionnelle"}]},{"enonce":"Touche la case de l’autorité qui se perd dès que les actes démentent les mots.","aide":"Cette autorité vient de la vie de celui qui parle.","type":"zone","document":"voix","multiple":false},{"enonce":"Complète la phrase du cours.","aide":"Pense au juge : un titre, pas un tempérament.","type":"trous","segments":["L’autorité institutionnelle vient de la ",0,", indépendamment des qualités de la personne."],"banque":["fonction","conduite","fortune","séduction"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Fonction : **institutionnelle** ; savoir : **de compétence** ; exemplarité : **morale** ; présence séduisante : **charismatique** (Weber)."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"C’est **« Sa vie garantit sa parole »** : l’autorité morale est révocable par la conduite."},{"cle":{"type":"trous","trous":[["fonction"]]},"affichage":"fonction","explication":"Elle vient de la **fonction** : le juge est écouté pour ce qu’il est chargé de faire."}]$ex$::jsonb),
  ('89a7ef1b-e7d4-5795-9755-56f02714ee82'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Je vous déclare unis","competence":"analyser-document","situation":"Un journal imaginaire note quatre énoncés entendus dans la même journée. Certains font ce qu’ils disent, d’autres non.","documents":[{"id":"enon","type":"tableau","titre":"Quatre énoncés","colonnes":["Qui parle","Où","Énoncé"],"lignes":[["Le maire","En mairie, devant les mariés","« Je vous déclare unis par le mariage. »"],["Un passant","Dans la rue, devant des inconnus","« Je vous déclare unis par le mariage. »"],["Léo","Au téléphone, à une amie","« Je te promets de venir. »"],["Léo","À la fenêtre","« Il fait beau. »"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui explique pourquoi la même phrase ne marie personne.","aide":"Compare avec la ligne du maire : qu’est-ce qui change ?","type":"zone","document":"enon","multiple":false},{"enonce":"Range chaque énoncé selon ce qu’il fait.","aide":"Promettre, c’est déjà s’engager ; constater, c’est seulement dire.","type":"categories","categories":[{"id":"c0","texte":"Fait ce qu’il dit"},{"id":"c1","texte":"Décrit seulement"}],"items":[{"id":"i0","texte":"Je te promets de venir"},{"id":"i1","texte":"Je jure de dire la vérité"},{"id":"i2","texte":"Le train est en retard"},{"id":"i3","texte":"Il fait beau"}]},{"enonce":"Pourquoi le passant ne marie-t-il personne ?","aide":"Les mots sont identiques à ceux du maire.","type":"choix","options":[{"id":"a","texte":"Le cadre institutionnel lui manque"},{"id":"b","texte":"Il ne dit pas les mots exacts de la formule"},{"id":"c","texte":"Les mariés ne se sont pas encore choisis"},{"id":"d","texte":"Il parle trop bas pour être entendu"}],"multiple":false},{"enonce":"Complète la formule d’Austin.","aide":"Certains énoncés accomplissent ce qu’ils disent.","type":"trous","segments":["Pour Austin, dire, c’est ",0,"."],"banque":["voir","faire","savoir","croire"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"C’est **« Dans la rue, devant des inconnus »** : sans cadre institutionnel, les mots seuls ne suffisent pas."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Une promesse ou un serment **font ce qu’ils disent** (performatifs) ; « il fait beau » et « le train est en retard » **décrivent** seulement."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les mots sont les mêmes : ce qui manque, c’est le **cadre institutionnel** (la mairie, la fonction du maire)."},{"cle":{"type":"trous","trous":[["faire"]]},"affichage":"faire","explication":"Pour Austin, **dire, c’est faire** : le performatif accomplit ce qu’il dit en le disant."}]$ex$::jsonb),
  ('89a7ef1b-e7d4-5795-9755-56f02714ee82'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le docteur qui vendait le complément","competence":"argumenter","situation":"Inès et Léo parlent d’une publicité vue à la télévision. Tu analyses l’argument de Léo et la façon dont Inès examine l’autorité invoquée.","documents":[{"id":"dial","type":"dialogue","modele":"sms","titre":"Un échange de messages","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Léo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Le Dr Marchal dit à la télé que ce complément fait maigrir."},{"qui":"Léo","texte":"S’il le dit, c’est vrai : il est docteur."},{"qui":"Inès","texte":"Il est juriste, pas nutritionniste. Et il vend lui-même le complément."},{"qui":"Léo","texte":"Ah. Je n’avais pas regardé."}]},{"id":"att","type":"tableau","titre":"Deux attitudes face à une autorité","colonnes":["","La confiance raisonnée","La soumission"],"lignes":[["Ce qu’elle fait","Elle s’enquiert de la compétence, des désaccords, des intérêts en jeu","Elle s’en dispense"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot que Léo utilise comme unique argument.","aide":"Quel titre est censé rendre la phrase vraie à lui seul ?","type":"zone","document":"dial","multiple":false},{"enonce":"Complète la définition.","aide":"C’est une faute de raisonnement qui porte un nom.","type":"trous","segments":["Invoquer la position de celui qui parle au lieu d’examiner ce qu’il dit est un ",0,"."],"banque":["mythe","serment","témoignage","sophisme"]},{"enonce":"Quelles deux questions de la confiance raisonnée Inès pose-t-elle ?","aide":"Relis la troisième réplique : deux remarques, deux questions.","type":"choix","options":[{"id":"a","texte":"La notoriété : est-il connu à la télévision ?"},{"id":"b","texte":"Les intérêts en jeu : a-t-il quelque chose à vendre ?"},{"id":"c","texte":"Les désaccords : d’autres experts disent-ils autre chose ?"},{"id":"d","texte":"La compétence : est-il spécialiste de ce sujet ?"}],"multiple":true},{"enonce":"Range chaque attitude.","aide":"L’une enquête, l’autre se dispense d’enquêter.","type":"categories","categories":[{"id":"c0","texte":"Confiance raisonnée"},{"id":"c1","texte":"Soumission"}],"items":[{"id":"i0","texte":"Je regarde si d’autres spécialistes sont en désaccord"},{"id":"i1","texte":"Je demande dans quelle spécialité cet expert a un diplôme"},{"id":"i2","texte":"Je ne vérifie rien car il a un titre"},{"id":"i3","texte":"Je le crois parce qu’il passe souvent à la télévision"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"Le mot est **docteur** : Léo invoque une position au lieu d’examiner ce que dit le Dr Marchal."},{"cle":{"type":"trous","trous":[["sophisme"]]},"affichage":"sophisme","explication":"C’est l’**argument d’autorité**, un **sophisme** : on remplace l’examen du propos par l’examen de la position."},{"cle":{"type":"choix","ids":["b","d"]},"explication":"Inès interroge la **compétence** (« juriste, pas nutritionniste ») et les **intérêts en jeu** (« il vend lui-même le complément »)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"La **confiance raisonnée** enquête sur la compétence et les désaccords ; la **soumission** s’en dispense."}]$ex$::jsonb),
