   $ex${"titre":"Émeute ou soulèvement ?","competence":"analyser-document","situation":"Deux journaux imaginaires racontent le même événement, avec deux titres. Tu observes ce que le choix d’un mot engage.","documents":[{"id":"titres","type":"tableau","titre":"Deux titres pour un même événement","colonnes":["Journal","Titre"],"lignes":[["Journal A","« Émeute dans le centre-ville »"],["Journal B","« Soulèvement dans le centre-ville »"]],"enteteLignes":true,"source":"Titres imaginaires, écrits pour l’exercice"}],"questions":[{"enonce":"Touche le titre qui présente l’événement comme un désordre.","aide":"Quel mot évoque le trouble plutôt que la cause ?","type":"zone","document":"titres","multiple":false},{"enonce":"Associe chaque mot à ce que son choix engage.","aide":"Chaque mot a un concurrent qui engage autre chose.","type":"association","gauche":[{"id":"g0","texte":"Choisir « exilé »"},{"id":"g1","texte":"Choisir « réforme »"},{"id":"g2","texte":"Choisir « recul »"},{"id":"g3","texte":"Choisir « soulèvement »"}],"droite":[{"id":"d0","texte":"Dire la perte"},{"id":"d1","texte":"Dire la légitimité"},{"id":"d2","texte":"Dire la contrainte subie"},{"id":"d3","texte":"Dire le progrès"}]},{"enonce":"Que montrent ces deux titres sur le fait de nommer ?","aide":"Un même événement, deux mots, deux jugements.","type":"choix","options":[{"id":"a","texte":"Nommer est un acte neutre qui décrit sans juger"},{"id":"b","texte":"Nommer, c’est déjà classer et hiérarchiser"},{"id":"c","texte":"Nommer rend un événement faux dès qu’il est raconté"},{"id":"d","texte":"Nommer n’a pas d’effet sur le lecteur"}],"multiple":false}]}$ex$::jsonb,
