   $ex${"titre":"La réunion des délégués","competence":"argumenter","situation":"Pendant une réunion de délégués imaginaire, Prisca cherche à parler. Tu identifies les trois gestes de pouvoir sur la parole.","documents":[{"id":"reunion","type":"dialogue","modele":"bulles","titre":"Extrait de la réunion","participants":[{"nom":"Prisca","emoji":"👩","cote":"gauche"},{"nom":"Max","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Prisca","texte":"Je demande la parole sur le règlement du foyer."},{"qui":"Max","texte":"Plus tard. J’ai encore dix minutes de choses à dire."},{"qui":"Prisca","texte":"Le règlement est injuste, et vous le savez, même si cela vous déplaît."},{"qui":"Max","texte":"Ce sujet n’est pas à l’ordre du jour. On passe, et je coupe ton micro."}]}],"questions":[{"enonce":"Touche le mot par lequel Prisca demande à prendre part au débat.","aide":"Cherche ce qu’elle réclame avant de s’exprimer.","type":"zone","document":"reunion","multiple":false},{"enonce":"Range chaque réplique selon le geste de pouvoir qu’elle illustre.","aide":"Demander, monopoliser, faire taire.","type":"categories","categories":[{"id":"c0","texte":"Prendre la parole"},{"id":"c1","texte":"Garder la parole"},{"id":"c2","texte":"Imposer le silence"}],"items":[{"id":"i0","texte":"Prisca : « Je demande la parole sur le règlement du foyer. »"},{"id":"i1","texte":"Max : « On passe, et je coupe ton micro. »"},{"id":"i2","texte":"Max : « J’ai encore dix minutes de choses à dire. »"}]},{"enonce":"Quelle réplique relève de la parrhêsia ?","aide":"La parrhêsia dit toute la vérité, même à qui peut vous nuire.","type":"choix","options":[{"id":"a","texte":"« J’ai encore dix minutes à dire »"},{"id":"b","texte":"« On passe, et je coupe ton micro »"},{"id":"c","texte":"« Je demande la parole sur le règlement »"},{"id":"d","texte":"« Le règlement est injuste, et vous le savez »"}],"multiple":false},{"enonce":"Complète la phrase du cours.","aide":"Même avant ce qu’on dit.","type":"trous","segments":["Prendre la parole quand elle vous était refusée est en soi un acte ",0,"."],"banque":["inutile","politique","décoratif","neutre"]}]}$ex$::jsonb,
