   $ex${"titre":"Une langue qu’on transforme","competence":"analyser-document","situation":"Une note de service imaginaire, dans un pays inventé, modifie le vocabulaire des journaux. Avec le regard de Klemperer, tu étudies comment on transforme les esprits en transformant les mots.","documents":[{"id":"note","type":"texte","genre":"source","titre":"Note de service d’un ministère imaginaire","blocs":["À compter de ce jour, on ne dira plus « censure » mais « protection de l’opinion », ni « prison » mais « maison de rééducation ». Les journaux qui n’appliqueront pas ces termes perdront leur autorisation de paraître."],"source":"Note imaginaire, écrite pour l’exercice"},{"id":"mots","type":"tableau","titre":"Un mot et son concurrent","colonnes":["Un mot","Son concurrent"],"lignes":[["Migrant","Exilé"],["Réforme","Recul"],["Émeute","Soulèvement"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui sert à faire passer la censure pour un bienfait.","aide":"Un mot qui évoque l’abri, le soin.","type":"zone","document":"note","multiple":false},{"enonce":"Range chaque geste de la note.","aide":"Un geste fait taire, l’autre fait dire autrement.","type":"categories","categories":[{"id":"c0","texte":"Imposer le silence"},{"id":"c1","texte":"Changer les mots"}],"items":[{"id":"i0","texte":"Remplacer « prison » par « maison de rééducation »"},{"id":"i1","texte":"Menacer ceux qui n’appliquent pas les nouveaux termes"},{"id":"i2","texte":"Appeler la censure « protection de l’opinion »"},{"id":"i3","texte":"Retirer son autorisation à un journal"}]},{"enonce":"Qu’a montré Klemperer dans LTI ?","aide":"La note de service est un exemple de ce mécanisme.","type":"choix","options":[{"id":"a","texte":"Comment un régime transforme la langue pour transformer les esprits"},{"id":"b","texte":"Comment un orateur gagne un procès par sa seule voix"},{"id":"c","texte":"Comment un poète invente des mots que personne n’avait dits"},{"id":"d","texte":"Comment un journal reste neutre en choisissant ses mots"}],"multiple":false},{"enonce":"Dans le tableau, touche le concurrent de « Réforme », qui dit une perte plutôt qu’un progrès.","aide":"Le mot s’oppose à « progrès » : on recule au lieu d’avancer.","type":"zone","document":"mots","multiple":false},{"enonce":"Complète la phrase du cours.","aide":"Un mot range la réalité et la place par rapport à une autre.","type":"trous","segments":["Nommer, c’est déjà ",0," et ",1,"."],"banque":["ignorer","oublier","classer","hiérarchiser"]}]}$ex$::jsonb,
