  ('1be24175-5c42-52e3-b425-8e90649e3056'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’albatros sur le pont","competence":"analyser-texte","situation":"Pour son carnet de lecture, Lou relit la première et la dernière strophe d’un célèbre poème de Baudelaire. Elle cherche ce que l’image de l’oiseau dit du poète.","documents":[{"id":"alb","type":"texte","genre":"poeme","titre":"L’Albatros (première et dernière strophes)","blocs":["Souvent, pour s’amuser, les hommes d’équipage","Prennent des albatros, vastes oiseaux des mers,","Qui suivent, indolents compagnons de voyage,","Le navire glissant sur les gouffres amers.","","Le Poète est semblable au prince des nuées","Qui hante la tempête et se rit de l’archer ;","Exilé sur le sol au milieu des huées,","Ses ailes de géant l’empêchent de marcher."],"auteur":"Charles Baudelaire, *Les Fleurs du mal*"}],"questions":[{"enonce":"Touche l’adjectif qui dit que les oiseaux suivent le navire sans se presser.","aide":"Cherche le mot qui évoque la lenteur et la nonchalance.","type":"zone","document":"alb","multiple":false},{"enonce":"Que symbolise l’albatros dans ce poème ?","aide":"La dernière strophe commence par « Le Poète est semblable… ».","type":"choix","options":[{"id":"a","texte":"Le marin, que le navire protège de toutes les tempêtes"},{"id":"b","texte":"Le voyageur, qui cherche à quitter son pays natal"},{"id":"c","texte":"Le poète, grand dans son élément, gêné chez les hommes"},{"id":"d","texte":"Le chasseur, qui se rit des archers et des flèches"}],"multiple":false},{"enonce":"Touche le mot du dernier vers qui devient une gêne dès que l’oiseau est sur le sol.","aide":"Ce qui lui permet de voler l’empêche de marcher.","type":"zone","document":"alb","multiple":false}]}$ex$::jsonb,
