  ('1be24175-5c42-52e3-b425-8e90649e3056'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ce que fait le poème","competence":"comprendre-langue","situation":"Un poème écrit pour l’exercice sert d’atelier : Théo y cherche les images et les sonorités, puis ce que fait la langue poétique.","documents":[{"id":"poeme","type":"texte","genre":"poeme","titre":"Soir","blocs":["Le soir sème ses cendres sur les saules ;","Le silence est un fleuve qui s’attarde ;","Mon cœur, tambour lointain, bat dans la nuit,","Et la lune est un œil qui me regarde."],"source":"Poème écrit pour l’exercice, dans l’esprit des poètes modernes"}],"questions":[{"enonce":"Touche le mot qui est comparé à un fleuve.","aide":"Cherche le sujet de la phrase « … est un fleuve ».","type":"zone","document":"poeme","multiple":false},{"enonce":"Range chaque relevé selon le moyen du poète qu’il illustre.","aide":"Une image donne à voir ; une sonorité se fait entendre.","type":"categories","categories":[{"id":"c0","texte":"Image (donne à voir)"},{"id":"c1","texte":"Sonorité (lie par le son)"}],"items":[{"id":"i0","texte":"Le son [s] revient dans « soir sème ses cendres sur les saules »"},{"id":"i1","texte":"« Le silence est un fleuve qui s’attarde »"},{"id":"i2","texte":"« Mon cœur, tambour lointain »"},{"id":"i3","texte":"« s’attarde » rime avec « regarde »"},{"id":"i4","texte":"« Et la lune est un œil qui me regarde »"}]},{"enonce":"Dire « le silence est un fleuve » plutôt que « il y a du silence » produit quel effet ?","aide":"La langue poétique s’écarte de la langue ordinaire.","type":"choix","options":[{"id":"a","texte":"Il rend la phrase plus rapide à comprendre"},{"id":"b","texte":"Il donne une leçon morale explicite"},{"id":"c","texte":"Il oblige à ralentir : le poème résiste et se relit"},{"id":"d","texte":"Il apporte une preuve au lecteur"}],"multiple":false},{"enonce":"Associe chaque moyen du poète à ce qu’il produit.","aide":"Quatre moyens, quatre effets.","type":"association","gauche":[{"id":"g0","texte":"Rythme et mètre"},{"id":"g1","texte":"Sonorités"},{"id":"g2","texte":"Image"},{"id":"g3","texte":"Écart avec la langue ordinaire"}],"droite":[{"id":"d0","texte":"Elle donne à voir"},{"id":"d1","texte":"Ils font entendre autre chose que le sens"},{"id":"d2","texte":"Elles lient les mots par le son"},{"id":"d3","texte":"Il oblige à ralentir"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"Le mot est **silence** : « le silence est un fleuve » est une métaphore."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c0"}},"explication":"Les comparaisons et métaphores **donnent à voir** ; l’allitération en [s] et la rime **lient les mots par le son**."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’**écart** avec la langue ordinaire oblige à **ralentir** : le poème ne se laisse pas consommer, c’est ce qui fait qu’on le relit."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"Le **rythme** fait entendre autre chose que le sens, les **sonorités** lient par le son, l’**image** donne à voir, l’**écart** oblige à ralentir."}]$ex$::jsonb),
  ('1be24175-5c42-52e3-b425-8e90649e3056'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Faut-il bannir les poètes ?","competence":"argumenter","situation":"Zoé et Malo, après le cours, confrontent Platon et Aristote sur la poésie. Un tableau donne la clé de l’argument d’Aristote.","documents":[{"id":"dial","type":"dialogue","modele":"bulles","titre":"Zoé et Malo, après le cours","participants":[{"nom":"Zoé","emoji":"👩","cote":"gauche"},{"nom":"Malo","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Zoé","texte":"Platon bannit les poètes de la Cité idéale : ils imitent les apparences, flattent les passions et éloignent du vrai."},{"qui":"Malo","texte":"Pourtant Aristote juge la poésie « plus philosophique » que l’histoire. Je ne vois pas pourquoi."}]},{"id":"ar","type":"tableau","titre":"Chez Aristote","colonnes":["","L’histoire","La poésie"],"lignes":[["Ce qu’elle dit","Le particulier","Le général"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce que Platon fait des poètes dans la Cité idéale.","aide":"Un verbe d’expulsion.","type":"zone","document":"dial","multiple":false},{"enonce":"Range chaque argument du côté de Platon ou d’Aristote.","aide":"L’un reproche, l’autre défend.","type":"categories","categories":[{"id":"c0","texte":"Platon (contre le poète)"},{"id":"c1","texte":"Aristote (pour le poète)"}],"items":[{"id":"i0","texte":"La poésie est plus philosophique que l’histoire"},{"id":"i1","texte":"Le poète éloigne du vrai"},{"id":"i2","texte":"Le poète flatte les passions"},{"id":"i3","texte":"Le poète imite les apparences"},{"id":"i4","texte":"La poésie dit le général"}]},{"enonce":"D’après le tableau, pourquoi la poésie est-elle plus philosophique que l’histoire ?","aide":"Relis les deux cases de la ligne du tableau.","type":"choix","options":[{"id":"a","texte":"Parce qu’elle dit le particulier quand l’histoire dit le général"},{"id":"b","texte":"Parce qu’elle s’appuie sur des preuves archivées"},{"id":"c","texte":"Parce qu’elle dit le général quand l’histoire dit le particulier"},{"id":"d","texte":"Parce qu’elle raconte des événements plus anciens"}],"multiple":false},{"enonce":"Les modernes déplacent la question. Complète leur idée.","aide":"Ce n’est pas un savoir de moins, c’est un savoir d’un autre ordre.","type":"trous","segments":["La poésie ne dit pas une vérité sur le monde : elle fait éprouver une ",0," de l’",1,"."],"banque":["quitter","habiter","copie","manière"]},{"enonce":"Associe chaque œuvre à ce qu’elle pose.","aide":"Une œuvre met en doute le poète ; l’autre célèbre sa puissance.","type":"association","gauche":[{"id":"g0","texte":"L’Ion de Platon"},{"id":"g1","texte":"Le mythe d’Orphée"}],"droite":[{"id":"d0","texte":"Un chant qui fait pleurer les pierres et arrache une morte aux Enfers"},{"id":"d1","texte":"Si le poète ne sait pas d’où lui vient ce qu’il dit, il ne peut pas en répondre"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"Le mot est **bannit** : Platon exclut les poètes de la Cité idéale."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1"}},"explication":"**Platon** reproche d’imiter, de flatter et d’éloigner du vrai ; **Aristote** loue la poésie qui dit le général et qui est plus philosophique."},{"cle":{"type":"choix","ids":["c"]},"explication":"La poésie dit le **général** quand l’histoire dit le **particulier** : elle est donc « plus philosophique »."},{"cle":{"type":"trous","trous":[["maniere"],["habiter"]]},"affichage":"manière · habiter","explication":"La poésie fait éprouver une **manière** de **l’habiter** : un savoir d’un autre ordre."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"L’**Ion** pose que le poète ne peut pas répondre de ce qu’il dit ; **Orphée** montre la puissance de la parole poétique sur le monde."}]$ex$::jsonb),
  ('5b0d48e5-583b-50a5-a625-fa6c48074f8f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Chaque époque ses mots","competence":"se-reperer-temps","situation":"Le CDI propose une exposition sur les codes de l’amour. Un tableau rappelle trois codes et leurs époques.","documents":[{"id":"codes","type":"tableau","titre":"Trois codes amoureux","colonnes":["Le code","Son époque"],"lignes":[["Le pétrarquisme","La Renaissance"],["La carte de Tendre","Le XVIIe siècle"],["L’amour courtois","Le Moyen Âge"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne l’époque de la carte de Tendre.","aide":"Cherche la ligne de la carte de Tendre.","type":"zone","document":"codes","multiple":false},{"enonce":"Associe chaque code à son trait.","aide":"Un code éloigne la dame, un autre accumule les images, un dernier trace une carte.","type":"association","gauche":[{"id":"g0","texte":"L’amour courtois"},{"id":"g1","texte":"Le pétrarquisme"},{"id":"g2","texte":"La carte de Tendre"}],"droite":[{"id":"d0","texte":"Les étapes du sentiment, comme un itinéraire"},{"id":"d1","texte":"Une dame inaccessible : le désir se nourrit de l’obstacle"},{"id":"d2","texte":"Le teint de lys, le feu et la glace"}]},{"enonce":"Range ces codes dans l’ordre chronologique.","aide":"Moyen Âge, Renaissance, XVIIe siècle.","type":"ordre","items":[{"id":"a","texte":"Le pétrarquisme"},{"id":"b","texte":"La carte de Tendre"},{"id":"c","texte":"L’amour courtois"}]}]}$ex$::jsonb,
