  ('5b0d48e5-583b-50a5-a625-fa6c48074f8f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un poème de pacotille","competence":"analyser-texte","situation":"Pour comprendre pourquoi on a moqué le pétrarquisme, Eva lit un poème écrit dans ce goût. Elle y repère les images convenues.","documents":[{"id":"sonnet","type":"texte","genre":"poeme","titre":"Pastiche pétrarquiste","blocs":["Votre teint est de lys, vos lèvres de corail ;","Je brûle dans la glace et je gèle en mon feu ;","Doux supplice, ô cruelle, et trop aimable aveu","Qui m’afflige et me plaît, me tue et me travaille."],"source":"Pastiche écrit pour l’exercice, dans le goût pétrarquiste de la Renaissance"}],"questions":[{"enonce":"Touche les deux mots qui s’opposent dans le deuxième vers.","aide":"Un élément brûle, l’autre gèle.","type":"zone","document":"sonnet","multiple":true},{"enonce":"Associe chaque passage à son procédé.","aide":"Une comparaison, une opposition, une alliance de contraires.","type":"association","gauche":[{"id":"g0","texte":"« Votre teint est de lys »"},{"id":"g1","texte":"« Je brûle dans la glace »"},{"id":"g2","texte":"« Doux supplice »"}],"droite":[{"id":"d0","texte":"Un oxymore : deux termes contradictoires"},{"id":"d1","texte":"Une antithèse : le feu et la glace"},{"id":"d2","texte":"Une image convenue : le teint comparé à une fleur"}]},{"enonce":"Pourquoi Du Bellay et Shakespeare finiront-ils par moquer de telles images ?","aide":"Chaque amant les reprend à son tour.","type":"choix","options":[{"id":"a","texte":"Parce qu’elles sont convenues et ne disent rien d’unique"},{"id":"b","texte":"Parce qu’elles sont trop difficiles à comprendre"},{"id":"c","texte":"Parce qu’elles viennent d’un poète de langue étrangère"},{"id":"d","texte":"Parce qu’elles sont trop proches de la vie réelle"}],"multiple":false},{"enonce":"Complète la définition du pétrarquisme.","aide":"Des clichés partagés par tous.","type":"trous","segments":["Le pétrarquisme est un ensemble d’images ",0," pour dire l’amour."],"banque":["convenues","inventées","cachées","gratuites"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m19"]},"explication":"Les mots sont **glace** et **feu** : le « feu et la glace » est un des clichés du pétrarquisme."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Le teint de lys est une **image convenue** ; feu et glace forment une **antithèse** ; « doux supplice » est un **oxymore**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Elles sont **convenues** : tous les amants reprennent les mêmes, qui ne disent donc rien d’unique."},{"cle":{"type":"trous","trous":[["convenues"]]},"affichage":"convenues","explication":"Un ensemble d’images **convenues** : c’est leur répétition qui les use."}]$ex$::jsonb),
  ('5b0d48e5-583b-50a5-a625-fa6c48074f8f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La même promesse à deux, et une lettre","competence":"argumenter","situation":"Aurore et Clara découvrent que Théo leur a écrit la même promesse. Plus loin, une autre voix écrit une lettre parce qu’elle ne peut pas dire ce qu’elle ressent.","documents":[{"id":"dial","type":"dialogue","modele":"sms","titre":"Aurore et Clara comparent leurs messages","participants":[{"nom":"Aurore","emoji":"👩","cote":"gauche"},{"nom":"Clara","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Aurore","texte":"Théo m’a écrit : « Tu es la seule, je te le jure. »"},{"qui":"Clara","texte":"Il m’a envoyé exactement la même phrase."},{"qui":"Aurore","texte":"Alors ses mots ne valent rien ?"},{"qui":"Clara","texte":"Ils valent ce qu’il a ressenti en les écrivant… ou rien du tout."}]},{"id":"lettre","type":"texte","genre":"lettre","titre":"Une lettre d’amour","blocs":["Mon amour, je t’écris parce que je n’arrive pas à te le dire. Je t’aime plus que mille mondes, mais ces mots sont ceux de tous les amants. Alors j’en invente un : tu es mon clairdelune. Je m’arrête ici : rien ne convient."],"source":"Lettre imaginaire, écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui sert à garantir la promesse de Théo.","aide":"Un verbe qui engage la parole donnée.","type":"zone","document":"dial","multiple":false},{"enonce":"Que montre l’échange entre Aurore et Clara ?","aide":"La même phrase vaut-elle pour deux personnes à la fois ?","type":"choix","options":[{"id":"a","texte":"Que Clara a tort de se fier aux promesses de Théo"},{"id":"b","texte":"Que les promesses d’amour sont toujours un secret"},{"id":"c","texte":"Que Théo est certainement sincère avec chacune"},{"id":"d","texte":"Que le discours amoureux peut fonctionner à vide"}],"multiple":false},{"enonce":"Associe chaque recours de la lettre au passage qui l’illustre.","aide":"Forcer la langue, inventer un mot, avouer que rien ne va.","type":"association","gauche":[{"id":"g0","texte":"Hyperbole"},{"id":"g1","texte":"Néologisme"},{"id":"g2","texte":"Silence"}],"droite":[{"id":"d0","texte":"« Clairdelune »"},{"id":"d1","texte":"« Rien ne convient »"},{"id":"d2","texte":"« Plus que mille mondes »"}]},{"enonce":"Pourquoi l’auteur de cette lettre écrit-il ?","aide":"Relis la première phrase de la lettre.","type":"choix","options":[{"id":"a","texte":"Parce qu’il préfère copier des lettres célèbres sans rien sentir"},{"id":"b","texte":"Parce qu’il veut prouver à sa famille qu’il est sincère"},{"id":"c","texte":"Parce qu’il trouve les mots ordinaires parfaitement exacts"},{"id":"d","texte":"Parce qu’il ne peut pas dire ce qu’il ressent"}],"multiple":false},{"enonce":"Complète ce que le chapitre demande.","aide":"On regarde ce que la parole fait, pas ce que les amants ressentent.","type":"trous","segments":["Il demande d’observer comment la parole ",0,", non de juger la ",1," des amants."],"banque":["ment","beauté","travaille","sincérité"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"Le mot est **jure** : un serment, qui ne vaut ici que par sa répétition identique."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est ce qui fait **Dom Juan** inquiétant : le discours amoureux **peut fonctionner à vide**, sa force étant dans ce qu’on sait dire, non dans ce qu’on ressent."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"L’**hyperbole** force la langue, le **néologisme** invente un mot, le **silence** avoue que rien ne convient."},{"cle":{"type":"choix","ids":["d"]},"explication":"Comme chez Rousseau ou Laclos, on **écrit parce qu’on ne peut pas dire** : la lettre donne une forme à l’absence et creuse le manque autant qu’elle le comble."},{"cle":{"type":"trous","trous":[["travaille"],["sincerite"]]},"affichage":"travaille · sincérité","explication":"Il s’agit d’observer comment la parole **travaille**, sans juger la **sincérité** des amants."}]$ex$::jsonb),
  ('a9e19c33-ef96-535d-af64-7bc3b077c2f3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une rumeur dans le groupe de la classe","competence":"analyser-texte","situation":"Un message circule dans le groupe de la classe de Maëlle. Elle veut comprendre pourquoi tout le monde le répète, et pourquoi le démenti n’y change rien.","documents":[{"id":"rumeur","type":"texte","genre":"recit","titre":"Lundi, mardi","blocs":["Lundi, un message passe dans le groupe de la classe : « Il paraît que Nils a triché au contrôle. » Personne n’a rien vu, mais chacun le croit puisqu’un autre l’a déjà dit.","Mardi, la professeure précise que c’est faux. Trop tard : dans les couloirs, on se souvient surtout de la première version."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui explique pourquoi chacun relaie la rumeur.","aide":"Personne n’a vérifié : qu’est-ce que chacun fait dès qu’un autre a parlé ?","type":"zone","document":"rumeur","multiple":false},{"enonce":"Que montre le démenti de mardi, qui ne change rien à ce qu’on pense de Nils ?","aide":"Relis la dernière phrase : peut-on faire en sorte que ce qui a été entendu n’ait pas été entendu ?","type":"choix","options":[{"id":"a","texte":"Le respect dû à celui dont on parle"},{"id":"b","texte":"La vérification de la rumeur"},{"id":"c","texte":"L’irréversibilité de la rumeur"},{"id":"d","texte":"La prudence de ceux qui la relaient"}],"multiple":false},{"enonce":"Associe chaque silence à ce qu’il fait.","aide":"Un seul silence est subi : celui du censeur. Les autres sont des choix, bons ou mauvais.","type":"association","gauche":[{"id":"g0","texte":"Silence de prudence"},{"id":"g1","texte":"Silence de complicité"},{"id":"g2","texte":"Silence de respect"},{"id":"g3","texte":"Silence imposé"}],"droite":[{"id":"d0","texte":"Retient ce qui blesserait inutilement"},{"id":"d1","texte":"Celui du censeur"},{"id":"d2","texte":"Se tait devant la douleur ou l’indicible"},{"id":"d3","texte":"Laisse faire ce qu’on désapprouve"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m26"]},"explication":"Le mot est **croit** : on relaie la rumeur en la tenant pour vérifiée, du seul fait qu’un autre l’a dite."},{"cle":{"type":"choix","ids":["c"]},"explication":"La rumeur est **irréversible** : un démenti n’efface pas ce qui a été entendu, et c’est ce qui rend la calomnie si grave."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"Le silence n’est pas l’absence de parole mais l’une de ses formes : **prudence** (on retient), **complicité** (on laisse faire), **respect** (devant l’indicible), **imposé** (par le censeur)."}]$ex$::jsonb),
  ('a9e19c33-ef96-535d-af64-7bc3b077c2f3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Que dire à celui qui frappe à la porte ?","competence":"argumenter","situation":"À l’atelier de philosophie, Anouk et Basile débattent d’un cas célèbre : un homme demande où se cache sa victime. Tu retrouves chez eux deux grandes positions sur le mensonge.","documents":[{"id":"debat","type":"dialogue","modele":"sms","titre":"Un débat d’atelier","participants":[{"nom":"Anouk","emoji":"👧","cote":"gauche"},{"nom":"Basile","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Anouk","texte":"Un homme sonne chez toi et veut savoir où se cache ton frère. Moi, je ne mentirais pas, même à lui : si tout le monde mentait dès que cela l’arrange, plus aucune parole ne vaudrait rien."},{"qui":"Basile","texte":"Mais cet homme n’a aucun droit à la vérité. On ne la doit qu’à celui qui y a droit."},{"qui":"Anouk","texte":"Alors tu décides toi-même qui mérite la vérité ?"}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui porte l’argument de Basile.","aide":"Basile pose une condition pour que la vérité soit due à quelqu’un.","type":"zone","document":"debat","multiple":false},{"enonce":"Range chaque idée du côté de Kant ou de Benjamin Constant.","aide":"Un des deux auteurs ne fait aucune exception ; l’autre regarde le destinataire.","type":"categories","categories":[{"id":"c0","texte":"Kant"},{"id":"c1","texte":"Benjamin Constant"}],"items":[{"id":"i0","texte":"La vérité n’est due qu’à celui qui y a droit"},{"id":"i1","texte":"Tout dépend de celui à qui l’on parle"},{"id":"i2","texte":"Le mensonge est interdit sans exception"},{"id":"i3","texte":"Mentir, c’est traiter autrui comme un moyen"}]},{"enonce":"Laquelle de ces phrases caricature la position de Kant au lieu de l’exposer ?","aide":"Exposer, c’est redire ses arguments. Caricaturer, c’est lui prêter une idée qu’il n’a pas.","type":"choix","options":[{"id":"a","texte":"Kant pense qu’un mensonge universalisé viderait la parole de sens"},{"id":"b","texte":"Kant veut qu’on dise tout à tout le monde, sans réfléchir"},{"id":"c","texte":"Kant refuse de traiter autrui comme un simple moyen"},{"id":"d","texte":"Kant maintient l’interdit même dans le cas du meurtrier"}],"multiple":false},{"enonce":"Complète le résumé du débat.","aide":"La première position ne connaît pas d’exception.","type":"trous","segments":["Pour Kant, le mensonge est ",0," interdit ; pour Constant, la vérité n’est due qu’à celui qui y a ",1,"."],"banque":["besoin","parfois","toujours","droit"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m43"]},"explication":"Le mot est **droit** : pour Basile, comme pour Benjamin Constant, dire la vérité n’est un devoir qu’envers celui qui y a droit."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"**Kant** : le mensonge est toujours interdit, parce qu’il traite autrui comme un moyen. **Constant** : tout dépend du destinataire, qui doit avoir droit à la vérité."},{"cle":{"type":"choix","ids":["b"]},"explication":"Kant ne demande pas de **tout dire** : il interdit de mentir. Il faut exposer son raisonnement (le langage ruiné, autrui traité comme un moyen) sans le caricaturer."},{"cle":{"type":"trous","trous":[["toujours"],["droit"]]},"affichage":"toujours · droit","explication":"Kant : **toujours** interdit. Constant : la vérité n’est un devoir qu’envers celui qui y a **droit**."}]$ex$::jsonb),
  ('a9e19c33-ef96-535d-af64-7bc3b077c2f3'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Publier ce soir ou parler demain ?","competence":"argumenter","situation":"Lina a filmé une dispute entre ses amis Zoé et Malo. Elle est tentée de la publier tout de suite. Tu l’aides à peser sa parole : le moment, la portée, et le droit contre le devoir.","documents":[{"id":"lina","type":"texte","genre":"recit","titre":"Le brouillon de Lina","blocs":["Lina se dit : « C’est la vérité, j’ai le droit de la montrer. » Elle prépare sa publication pour ce soir, devant ses douze mille abonnés.","Zoé pleure encore. Lina hésite : demain, tout le monde sera plus calme."],"source":"Récit écrit pour l’exercice"},{"id":"options","type":"tableau","titre":"Les trois options de Lina","colonnes":["Option","Quand","Devant qui","Ce qui peut arriver"],"lignes":[["A. Publier la vidéo","Ce soir","12 000 abonnés","Zoé l’apprend en ligne"],["B. En parler d’abord à Zoé","Demain","Zoé seule","Zoé répond avant que tout soit dit"],["C. Envoyer la vidéo à Malo","Ce soir","Malo seul","La dispute repart"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne la portée de la parole si Lina choisit l’option A.","aide":"La portée, c’est devant qui l’on parle.","type":"zone","document":"options","multiple":false},{"enonce":"Range chaque remarque : relève-t-elle du moment juste (kairos) ou de la portée ?","aide":"Le kairos dit « quand ». La portée dit « devant qui et avec quelles suites ».","type":"categories","categories":[{"id":"c0","texte":"Le moment (kairos)"},{"id":"c1","texte":"La portée"}],"items":[{"id":"i0","texte":"Douze mille personnes verront la vidéo"},{"id":"i1","texte":"Une vidéo en ligne ne s’efface jamais vraiment"},{"id":"i2","texte":"Demain, la colère sera retombée"},{"id":"i3","texte":"Zoé pleure encore ce soir"}]},{"enonce":"Lina pense : « C’est vrai, donc je dois le publier. » Que confond-elle ?","aide":"Avoir le droit de dire quelque chose, est-ce être obligé de le dire ?","type":"choix","options":[{"id":"a","texte":"Le mensonge et la vérité"},{"id":"b","texte":"Le droit de dire et le devoir de tout dire"},{"id":"c","texte":"Le silence de respect et le silence imposé"},{"id":"d","texte":"La rumeur et le témoignage"}],"multiple":false},{"enonce":"Complète la leçon que Lina en tire.","aide":"Une permission d’un côté, une obligation de l’autre.","type":"trous","segments":["Le ",0," de dire n’est pas le ",1," de tout dire."],"banque":["plaisir","hasard","droit","devoir"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"La case est **12 000 abonnés** : mesurer la portée, c’est se demander devant qui l’on parle et avec quelles conséquences."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Le **kairos** (savoir le moment) : ce soir ou demain. La **portée** : le nombre de spectateurs et la durée des conséquences."},{"cle":{"type":"choix","ids":["b"]},"explication":"Lina confond le **droit** de dire et le **devoir** de tout dire. Que la vidéo soit vraie ne suffit pas : il faut parler à propos et mesurer la portée."},{"cle":{"type":"trous","trous":[["droit"],["devoir"]]},"affichage":"droit · devoir","explication":"Le **droit** de dire n’est pas le **devoir** de tout dire : c’est une question de responsabilité, pas de politesse."}]$ex$::jsonb),
  ('c06a9fcb-91e4-5a78-9d38-17ada25871b6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"De Séville aux Antilles, puis à Valladolid","competence":"se-reperer-espace","situation":"Dans ton cahier d’histoire des idées, tu situes l’événement par lequel l’Europe a découvert d’autres peuples, puis le débat qu’il a provoqué, avant de nommer les attitudes possibles devant l’autre.","documents":[{"id":"carte","type":"carte","titre":"La traversée de 1492","fond":"monde","cadrage":[-90,10,0,45],"lieux":[{"id":"z1","lieu":"seville","symbole":"lettre","lettre":"A","teinte":"violet"},{"id":"z2","lon":-75,"lat":22,"symbole":"lettre","lettre":"B","teinte":"violet"}],"traits":[{"points":["seville",[-75,22]],"style":"fleche","teinte":"corail"}],"source":"Carte simplifiée"},{"id":"frise","type":"frise","titre":"Deux dates","debut":1480,"fin":1560,"pas":20,"evenements":[{"id":"z3","date":1492,"nom":"Colomb"},{"id":"z4","date":1550,"nom":"Valladolid"}]}],"questions":[{"enonce":"Touche le lieu où Colomb atteint l’Amérique en croyant aborder les Indes.","aide":"Colomb part d’Espagne en traversant l’Atlantique vers l’ouest.","type":"zone","document":"carte","multiple":false},{"enonce":"Combien d’années séparent l’arrivée de Colomb de la controverse de Valladolid ?","aide":"Lis les deux dates sur la frise et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque attitude devant l’autre à ce qu’elle affirme.","aide":"La plus généreuse en apparence (idéaliser) reste une projection.","type":"association","gauche":[{"id":"g0","texte":"Réduire"},{"id":"g1","texte":"Idéaliser"},{"id":"g2","texte":"Comprendre"}],"droite":[{"id":"d0","texte":"L’autre a une culture entière, avec sa cohérence"},{"id":"d1","texte":"L’autre est un sauvage, un être inachevé"},{"id":"d2","texte":"L’autre vit dans l’innocence que nous avons perdue"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le lieu est **B**, dans les Antilles : Colomb y arrive en 1492, en croyant aborder les Indes."},{"cle":{"type":"nombre","valeur":58,"tolerance":0},"affichage":"58 ans","explication":"1550 − 1492 = **58 ans** : en moins de soixante ans, la rencontre est devenue une question de droit."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Réduire** légitime la conquête, **idéaliser** fabrique le bon sauvage, **comprendre** est la seule attitude qui regarde vraiment."}]$ex$::jsonb),
  ('c06a9fcb-91e4-5a78-9d38-17ada25871b6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le greffier de Valladolid","competence":"analyser-document","situation":"Un greffier imaginaire note les débuts de la séance de 1550, à Valladolid. Tu y retrouves les deux orateurs et tu mesures ce que révèle le débat lui-même.","documents":[{"id":"greffier","type":"texte","genre":"source","titre":"Journal du greffier","blocs":["Séance d’ouverture. Les juges demandent s’il faut reconnaître aux Indiens une âme et des droits.","Le premier orateur, qui a vu la conquête de ses yeux, plaide pour leur pleine humanité. Le second invoque la guerre juste et la servitude naturelle décrite par Aristote."],"source":"Journal imaginaire, écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit ce que les juges se demandent d’abord à propos des Indiens.","aide":"Il s’agit de savoir s’ils sont de pleins humains : quel mot dit cela ?","type":"zone","document":"greffier","multiple":false},{"enonce":"Associe chaque nom à ce que le document permet de lui attribuer.","aide":"Le premier orateur « a vu la conquête de ses yeux » ; le second cite Aristote.","type":"association","gauche":[{"id":"g0","texte":"Las Casas"},{"id":"g1","texte":"Sepúlveda"},{"id":"g2","texte":"Colomb"}],"droite":[{"id":"d0","texte":"A vu la conquête et plaide pour la pleine humanité"},{"id":"d1","texte":"Atteint l’Amérique en 1492"},{"id":"d2","texte":"Invoque la guerre juste et la servitude naturelle"}]},{"enonce":"Que révèle le fait que cette question ait dû être posée ?","aide":"Pense à la phrase du cours : que la question ait dû être posée en dit autant que la réponse.","type":"choix","options":[{"id":"a","texte":"Que la conquête a d’abord été vécue comme un doute sur l’humanité des Indiens"},{"id":"b","texte":"Que la question de l’âme des Indiens était réglée depuis longtemps"},{"id":"c","texte":"Que seuls les juges espagnols s’intéressaient aux Indiens"},{"id":"d","texte":"Que les Indiens avaient été consultés avant la conquête"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"C’est la controverse de Valladolid.","type":"trous","segments":["En 1550, l’Espagne organise un ",0," public sur les droits des ",1,"."],"banque":["débat","marchands","Indiens","procès"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"Le mot est **âme** : la question posée est de savoir si les Indiens ont une âme et des droits."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**Las Casas** a vu la conquête et défend leur humanité ; **Sepúlveda** s’appuie sur la guerre juste et sur Aristote ; **Colomb** n’est pas à la séance, il ouvre l’histoire en 1492."},{"cle":{"type":"choix","ids":["a"]},"explication":"Qu’on ait dû **demander** si les Indiens avaient une âme dit déjà beaucoup de la conquête : la question en dit autant que la réponse."},{"cle":{"type":"trous","trous":[["debat"],["indiens"]]},"affichage":"débat · Indiens","explication":"La controverse de Valladolid est un **débat** public sur les droits des **Indiens**."}]$ex$::jsonb),
  ('c06a9fcb-91e4-5a78-9d38-17ada25871b6'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Qui est le barbare ?","competence":"analyser-texte","situation":"Tu prépares un commentaire de « Des cannibales » de Montaigne. Un passage adapté et un tableau t’aident à retourner le jugement, puis à nommer l’attitude de Montaigne et le mot de Lévi-Strauss.","documents":[{"id":"montaigne","type":"texte","genre":"source","titre":"Des cannibales (adapté)","blocs":["Montaigne rapporte que les Tupinambas mangent leurs ennemis après leur mort, selon un rite. Il n’approuve pas ce rite, mais il observe que, dans les guerres de religion, on torture et on brûle des hommes encore vivants.","Il écrit : « chacun appelle barbarie ce qui n’est pas de son usage »."],"source":"D’après Montaigne, *Essais*, I, 31 — texte adapté ; seule la phrase entre guillemets est de Montaigne"},{"id":"cruautes","type":"tableau","titre":"Deux cruautés","colonnes":["La cruauté","Sur qui elle s’exerce"],"lignes":[["Celle des Tupinambas","Sur un mort"],["Celle des guerres de religion","Sur un vivant"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit sur qui s’exerce la cruauté des guerres de religion.","aide":"Compare avec le rite des Tupinambas, qui s’exerce après la mort.","type":"zone","document":"montaigne","multiple":false},{"enonce":"Quel est le geste de Montaigne dans ce passage ?","aide":"Montaigne ne dit pas que tout se vaut : relis le cours sur ce point.","type":"choix","options":[{"id":"a","texte":"Il admire les Tupinambas comme un peuple resté dans l’innocence"},{"id":"b","texte":"Il affirme que tous les usages se valent et qu’il ne faut plus rien juger"},{"id":"c","texte":"Il suspend son jugement le temps de regarder, puis constate que sa mesure était locale"},{"id":"d","texte":"Il condamne les Tupinambas au nom des usages de l’Europe"}],"multiple":false},{"enonce":"Range chaque remarque selon l’attitude qu’elle exprime.","aide":"Une attitude justifie la conquête, une autre projette un rêve, la troisième regarde.","type":"categories","categories":[{"id":"c0","texte":"Réduire"},{"id":"c1","texte":"Idéaliser"},{"id":"c2","texte":"Comprendre"}],"items":[{"id":"i0","texte":"Ils vivent dans l’innocence que nous avons perdue"},{"id":"i1","texte":"Ces gens-là sont des sauvages inachevés"},{"id":"i2","texte":"Leur culture a sa cohérence propre : regardons-la"},{"id":"i3","texte":"La conquête est donc légitime"}]},{"enonce":"Complète la définition.","aide":"Le mot dit que sa propre culture est tenue pour le centre.","type":"trous","segments":["Dans *Race et histoire*, Lévi-Strauss appelle ",0," le fait de juger les autres cultures à l’aune de la sienne."],"banque":["ethnocentrisme","orientalisme","relativisme","humanisme"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m37"]},"explication":"Le mot est **vivants** : pour Montaigne, torturer des vivants est plus cruel que manger un mort."},{"cle":{"type":"choix","ids":["c"]},"explication":"Montaigne **suspend** le jugement le temps de regarder, et découvre que la mesure avec laquelle on jugeait était locale. Il ne dit pas que tout se vaut."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c0"}},"explication":"**Réduire** (sauvages, conquête légitime), **idéaliser** (le bon sauvage, une projection), **comprendre** (une culture entière avec sa cohérence)."},{"cle":{"type":"trous","trous":[["ethnocentrisme"]]},"affichage":"ethnocentrisme","explication":"C’est l’**ethnocentrisme** : chaque société tend à réserver le nom d’humanité à ses propres membres."}]$ex$::jsonb),
  ('bf7993d7-c076-572f-9825-54e86605b90a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les marges d’une carte du Moyen Âge","competence":"analyser-document","situation":"Tu observes une mappemonde imaginaire dans l’esprit des cartes médiévales. Ce qu’on dessine aux bords du monde en dit long sur la manière dont on se représentait l’étranger.","documents":[{"id":"mappemonde","type":"schema","titre":"Mappemonde imaginaire","largeur":320,"hauteur":260,"elements":[{"forme":"ellipse","cx":160,"cy":130,"rx":105,"ry":85,"teinte":"sable","motif":"clair"},{"forme":"texte","x":160,"y":135,"texte":"Terres connues","ancre":"milieu","italique":true},{"forme":"emoji","x":45,"y":120,"emoji":"🐺","taille":32,"id":"z1","zone":true},{"forme":"texte","x":45,"y":150,"texte":"tête de chien","taille":"petit","ancre":"milieu"},{"forme":"emoji","x":275,"y":120,"emoji":"👹","taille":32,"id":"z2","zone":true},{"forme":"texte","x":275,"y":150,"texte":"homme sans tête","taille":"petit","ancre":"milieu"},{"forme":"emoji","x":160,"y":28,"emoji":"🐉","taille":32,"id":"z3","zone":true},{"forme":"texte","x":160,"y":56,"texte":"dragon","taille":"petit","ancre":"milieu"},{"forme":"emoji","x":160,"y":220,"emoji":"⛪","taille":32,"id":"z4","zone":true},{"forme":"texte","x":160,"y":248,"texte":"ville chrétienne","taille":"petit","ancre":"milieu"}],"source":"Schéma imaginaire, dans l’esprit des cartes médiévales"}],"questions":[{"enonce":"Touche les trois créatures monstrueuses que la carte rejette aux marges du monde.","aide":"Ce qui est connu occupe le centre : les monstres sont aux bords.","type":"zone","document":"mappemonde","multiple":true},{"enonce":"Associe chaque figure de l’étranger à son époque.","aide":"La carte du document correspond à l’une de ces figures.","type":"association","gauche":[{"id":"g0","texte":"Le barbare"},{"id":"g1","texte":"Le monstre"},{"id":"g2","texte":"L’exotique"},{"id":"g3","texte":"L’Orient rêvé de Said"}],"droite":[{"id":"d0","texte":"L’âge classique"},{"id":"d1","texte":"Le Moyen Âge"},{"id":"d2","texte":"Le XIXe siècle"},{"id":"d3","texte":"La Grèce"}]},{"enonce":"Complète le constat du chapitre.","aide":"Elle en dit autant sur celui qui la trace que sur celui qu’elle décrit.","type":"trous","segments":["Une représentation de l’étranger est toujours, aussi, un ",0,"."],"banque":["documentaire","souvenir","autoportrait","mensonge"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2","z3"]},"explication":"Le **cynocéphale, l’homme sans tête et le dragon** peuplent les marges : au Moyen Âge, l’étranger lointain est figuré en **monstre**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Le **barbare** grec, le **monstre** médiéval, l’**exotique** de l’âge classique, l’**orientalisme** du XIXe siècle : chaque époque a sa figure de l’étranger."},{"cle":{"type":"trous","trous":[["autoportrait"]]},"affichage":"autoportrait","explication":"Une représentation de l’étranger est toujours, aussi, un **autoportrait** : la carte médiévale dit ce que l’Europe craint et ignore."}]$ex$::jsonb),
  ('bf7993d7-c076-572f-9825-54e86605b90a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre persane à la manière de Montesquieu","competence":"analyser-texte","situation":"Tu lis une lettre imaginaire, écrite à la manière des Lettres persanes. Un voyageur étranger décrit Paris ; tu repères le procédé qui rend notre monde étrange.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’Usbek à un ami (imaginée)","blocs":["Les habitants de cette ville passent leur journée à regarder de petites vitres lumineuses. Ils les tiennent dans la main, leur parlent, et trouvent cela tout à fait naturel.","Quand j’ai demandé pourquoi, on m’a répondu d’un air étonné : « Mais c’est comme ça ! » Il m’a semblu que c’était la plus mauvaise raison du monde."],"source":"Lettre écrite pour l’exercice, à la manière des *Lettres persanes* de Montesquieu"}],"questions":[{"enonce":"Touche le mot par lequel les habitants jugent évident ce que le voyageur trouve étrange.","aide":"Cherche le mot qui dit que ce comportement leur paraît aller de soi.","type":"zone","document":"lettre","multiple":false},{"enonce":"Quel est le procédé de ce texte ?","aide":"Qui décrit ici ? Un étranger qui regarde notre monde.","type":"choix","options":[{"id":"a","texte":"La défamiliarisation : rendre étrange ce qui nous est familier"},{"id":"b","texte":"La monstruosité : peupler les marges du monde"},{"id":"c","texte":"L’orientalisme : décrire un Orient rêvé et immobile"},{"id":"d","texte":"L’idéalisation : voir dans l’autre l’innocence perdue"}],"multiple":false},{"enonce":"Associe chaque œuvre à son procédé.","aide":"Chaque œuvre confie le regard à quelqu’un qui vient d’ailleurs.","type":"association","gauche":[{"id":"g0","texte":"Lettres persanes"},{"id":"g1","texte":"L’Ingénu"},{"id":"g2","texte":"Micromégas"}],"droite":[{"id":"d0","texte":"Deux Persans à Paris trouvent nos usages bizarres"},{"id":"d1","texte":"Un géant venu d’ailleurs regarde les humains"},{"id":"d2","texte":"Le regard naïf démasque l’arbitraire de nos usages"}]},{"enonce":"Pourquoi la phrase « Mais c’est comme ça ! » est-elle « la plus mauvaise raison du monde » pour le voyageur ?","aide":"Une raison qui n’en est pas une : elle remplace l’examen par l’habitude.","type":"choix","options":[{"id":"a","texte":"Elle prend une habitude pour une nécessité, sans l’examiner"},{"id":"b","texte":"Elle répond de façon précise et argumentée à la question posée"},{"id":"c","texte":"Elle prouve que les habitants cachent volontairement la vérité"},{"id":"d","texte":"Elle montre que les habitants sont cruels avec les étrangers"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m28"]},"explication":"Le mot est **naturel** : le texte montre que ce qu’on tient pour naturel est en réalité une habitude, et que le regard étranger le fait voir."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le texte **défamiliarise** : un étranger décrit nos usages, et ils deviennent étranges. C’est le procédé de Montesquieu dans les *Lettres persanes*."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Dans les trois œuvres, un regard **venu d’ailleurs** ou **naïf** démasque l’arbitraire de ce que nous tenons pour naturel."},{"cle":{"type":"choix","ids":["a"]},"explication":"« C’est comme ça » **prend l’habitude pour une loi de nature** et dispense d’examiner. La défamiliarisation sert justement à interrompre ce réflexe."}]$ex$::jsonb),
  ('bf7993d7-c076-572f-9825-54e86605b90a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le slogan de l’agence de voyages","competence":"analyser-document","situation":"Une agence de voyages imaginaire vend un « Orient éternel ». Tu démontes sa publicité avec les questions du chapitre : quelle figure est construite, par quels moyens, à qui profite-t-elle ?","documents":[{"id":"pub","type":"texte","genre":"article","titre":"Publicité d’une agence fictive","blocs":["**Orient mystérieux.** Là-bas, le temps s’arrête : des palais, des marchés parfumés, une douceur sans âge. Un pays qui n’a pas changé depuis mille ans, et qui vous attend.","Partez en quinze jours : nous avons tout prévu, vous n’aurez rien à comprendre."],"source":"Publicité écrite pour l’exercice"},{"id":"grille","type":"tableau","titre":"Les questions du chapitre","colonnes":["La question","Ce qu’elle cherche"],"lignes":[["Quelle figure est construite ?","Le portrait exact"],["Par quels moyens ?","Images, mots, cadrages"],["À qui profite-t-elle ?","L’intérêt servi"],["Que révèle-t-elle de celui qui la trace ?","L’autoportrait involontaire"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit que cet Orient serait immobile.","aide":"Un Orient « rêvé et immobile » : quel verbe dit que le temps ne passe pas ?","type":"zone","document":"pub","multiple":false},{"enonce":"Range chaque phrase selon le trait du stéréotype qu’elle illustre.","aide":"Trois traits : il dispense de connaître, il se transmet sans examen, il retient ce qui le vérifie.","type":"categories","categories":[{"id":"c0","texte":"Il est économique"},{"id":"c1","texte":"Il circule vite"},{"id":"c2","texte":"Il se confirme lui-même"}],"items":[{"id":"i0","texte":"Un seul slogan suffit : nul besoin de rencontrer personne"},{"id":"i1","texte":"« Orient mystérieux » dispense de s’informer sur le pays réel"},{"id":"i2","texte":"Le slogan est repris par mille comptes sans que personne le vérifie"},{"id":"i3","texte":"On retient le touriste qui confirme l’image, pas les dix qui la démentent"}]},{"enonce":"À qui profite cette représentation de l’étranger ?","aide":"Relis la deuxième phrase de la publicité : elle dit ce que le client n’aura pas à faire.","type":"choix","options":[{"id":"a","texte":"À la science, qui obtient des faits précis"},{"id":"b","texte":"À personne, car elle est neutre"},{"id":"c","texte":"À l’agence, qui vend un rêve facile à acheter"},{"id":"d","texte":"Aux habitants du pays, mieux connus des voyageurs"}],"multiple":false},{"enonce":"Complète la phrase de Said.","aide":"Le mot est déjà dans la publicité.","type":"trous","segments":["L’orientalisme construit un Orient rêvé et ",0,", qui en dit plus sur l’Occident que sur l’Orient."],"banque":["inconnu","immobile","moderne","violent"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m6"]},"explication":"Le mot est **s’arrête** : la publicité fabrique l’Orient figé du discours orientaliste."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c2"}},"explication":"Le stéréotype est **économique** (il dispense de connaître), il **circule vite** (sans examen) et il **se confirme lui-même** (on remarque ce qui le vérifie)."},{"cle":{"type":"choix","ids":["c"]},"explication":"La représentation sert **l’agence** : un Orient simple, immobile et prêt à consommer se vend mieux qu’un pays réel et complexe."},{"cle":{"type":"trous","trous":[["immobile"]]},"affichage":"immobile","explication":"Un Orient rêvé et **immobile** : c’est exactement ce que la publicité fabrique avec « le temps s’arrête »."}]$ex$::jsonb),
  ('e4b19543-7bf3-58aa-8488-2d07941208f6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le cosmos que l’on croyait habiter","competence":"observer-schema","situation":"Au musée des sciences, une maquette montre l’univers d’Aristote et de Ptolémée. Tu y repères les deux grands domaines du monde d’avant, avant de voir ce qui les a fait voler en éclats.","documents":[{"id":"cosmos","type":"schema","titre":"Le cosmos d’Aristote et de Ptolémée","largeur":320,"hauteur":260,"elements":[{"forme":"cercle","cx":160,"cy":130,"r":112,"teinte":"ciel","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":160,"cy":130,"r":64,"teinte":"sable","motif":"clair","id":"z2","zone":true},{"forme":"cercle","cx":160,"cy":130,"r":22,"teinte":"bleu","motif":"plein"},{"forme":"emoji","x":160,"y":138,"emoji":"🌍","taille":28},{"forme":"texte","x":160,"y":36,"texte":"Sphère des étoiles fixes","taille":"petit","ancre":"milieu"},{"forme":"texte","x":160,"y":80,"texte":"Orbite de la Lune","taille":"petit","ancre":"milieu","italique":true}],"source":"Schéma simplifié, sans échelle"}],"questions":[{"enonce":"Touche le domaine sublunaire, où règnent le changement et la corruption.","aide":"Sublunaire : « sous la Lune ». Cherche la région limitée par l’orbite de la Lune.","type":"zone","document":"cosmos","multiple":false},{"enonce":"Range chaque caractéristique dans le bon domaine du cosmos.","aide":"Sous la Lune, tout se transforme ; au-dessus, tout est parfait et éternel.","type":"categories","categories":[{"id":"c0","texte":"Sublunaire"},{"id":"c1","texte":"Supralunaire"}],"items":[{"id":"i0","texte":"La naissance et la mort des êtres"},{"id":"i1","texte":"Le changement et la corruption"},{"id":"i2","texte":"Les mouvements circulaires éternels"},{"id":"i3","texte":"La perfection"}]},{"enonce":"Complète la description du cosmos.","aide":"Le schéma montre une dernière sphère au-delà de laquelle il n’y a rien.","type":"trous","segments":["Ce cosmos est fini, ",0," et hiérarchisé, avec la Terre immobile au centre."],"banque":["infini","désert","mouvant","clos"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le domaine **sublunaire** est la région comprise sous l’orbite de la Lune : c’est là que tout change et se corrompt."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Le **sublunaire** est le monde du changement et de la corruption ; le **supralunaire** est celui de la perfection et des mouvements circulaires éternels."},{"cle":{"type":"trous","trous":[["clos"]]},"affichage":"clos","explication":"Le cosmos d’Aristote et de Ptolémée est **clos** : fini, fermé par la sphère des étoiles, et ordonné du centre vers le bord."}]$ex$::jsonb),
  ('e4b19543-7bf3-58aa-8488-2d07941208f6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Soixante ans pour changer de ciel","competence":"se-reperer-temps","situation":"Pour un exposé, Samia place sur une frise les grandes étapes qui ont fait passer l’Europe du monde clos à l’univers infini. Tu dates, tu calcules, puis tu relies chaque savant à son apport.","documents":[{"id":"frise","type":"frise","titre":"Du monde clos à l’univers infini","debut":1540,"fin":1700,"pas":20,"evenements":[{"id":"z1","date":1543,"nom":"Copernic"},{"id":"z2","date":1600,"nom":"Bruno"},{"id":"z3","date":1610,"nom":"Lunette"},{"id":"z4","date":1633,"nom":"Condamnation"},{"id":"z5","date":1687,"nom":"Newton"}],"source":"Dates tirées du cours"}],"questions":[{"enonce":"Touche l’événement où le ciel et la terre sont unifiés sous une même loi de gravitation.","aide":"C’est la dernière date de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le Soleil au centre de Copernic de la loi de gravitation de Newton ?","aide":"Soustrais la date de Copernic à celle de Newton.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque savant à ce qu’il établit.","aide":"Bruno est celui qui est brûlé ; Galilée est celui de la lunette.","type":"association","gauche":[{"id":"g0","texte":"Copernic"},{"id":"g1","texte":"Giordano Bruno"},{"id":"g2","texte":"Galilée"},{"id":"g3","texte":"Newton"}],"droite":[{"id":"d0","texte":"Une même loi de gravitation pour le ciel et la terre"},{"id":"d1","texte":"L’univers infini et la pluralité des mondes"},{"id":"d2","texte":"Le Soleil au centre, d’abord comme hypothèse de calcul"},{"id":"d3","texte":"Les satellites de Jupiter et les reliefs de la Lune"}]},{"enonce":"Pourquoi les satellites de Jupiter ébranlent-ils le cosmos d’Aristote ?","aide":"Dans ce cosmos, tout tourne autour de la Terre.","type":"choix","options":[{"id":"a","texte":"Ils prouvent que la Lune est parfaitement lisse et sans relief"},{"id":"b","texte":"Ils montrent que des astres tournent autour d’un autre centre que la Terre"},{"id":"c","texte":"Ils confirment que le ciel est fait d’une matière éternelle et parfaite"},{"id":"d","texte":"Ils établissent que la Terre reste immobile au centre de tout"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"C’est **1687, Newton** : une même loi de gravitation vaut pour le ciel et pour la terre."},{"cle":{"type":"nombre","valeur":144,"tolerance":0},"affichage":"144 ans","explication":"1687 − 1543 = **144 ans** : le changement de cosmos s’étale sur près d’un siècle et demi."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"**Copernic** : le Soleil au centre. **Bruno** : l’infini des mondes. **Galilée** : satellites de Jupiter, reliefs de la Lune. **Newton** : la gravitation universelle."},{"cle":{"type":"choix","ids":["b"]},"explication":"Si des astres tournent autour de **Jupiter**, alors tout ne tourne pas autour de la Terre : la position centrale de l’homme est atteinte."}]$ex$::jsonb),
  ('e4b19543-7bf3-58aa-8488-2d07941208f6'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le vertige d’une nuit d’été","competence":"analyser-texte","situation":"Après un cours sur Pascal, Léa écrit une lettre sur une nuit passée à regarder les étoiles. Tu rapproches son expérience de la phrase célèbre de Pascal, puis tu dresses le bilan de ce que perd et de ce que gagne l’homme.","documents":[{"id":"pascal","type":"texte","genre":"source","titre":"Une phrase de Pascal","blocs":["« Le silence éternel de ces espaces infinis m’effraie. »"],"source":"Pascal, *Pensées* (publiées en 1670)"},{"id":"lea","type":"texte","genre":"lettre","titre":"Lettre de Léa (imaginée)","blocs":["Cette nuit, au bord du lac, j’ai levé la tête. Tant d’étoiles que la Terre m’a paru toute petite : j’ai senti comme un vertige.","Puis je me suis dit que j’étais là pour le savoir, et que ce ciel, lui, ne savait pas que j’existais."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot de la lettre qui exprime ce que Pascal appelle l’effroi.","aide":"Cherche le mot qui dit l’impression de perdre pied devant l’immensité.","type":"zone","document":"lea","multiple":false},{"enonce":"Quelle idée de Pascal retrouve-t-on dans la dernière phrase de la lettre ?","aide":"Pascal fait de la pensée la grandeur du roseau.","type":"choix","options":[{"id":"a","texte":"L’homme doit détourner son regard du ciel pour retrouver la paix"},{"id":"b","texte":"Le Soleil est au centre et la Terre tourne autour de lui"},{"id":"c","texte":"L’univers est ordonné de façon que chaque chose ait sa place"},{"id":"d","texte":"L’homme est écrasé par l’univers, mais il le sait, et l’univers ne sait rien"}],"multiple":false},{"enonce":"Range chaque élément : est-il perdu ou établi dans ce changement de cosmos ?","aide":"La nature n’est plus un livre à déchiffrer : elle devient autre chose.","type":"categories","categories":[{"id":"c0","texte":"Ce qui se perd"},{"id":"c1","texte":"Ce qui s’établit"}],"items":[{"id":"i0","texte":"La loi de gravitation, valable partout"},{"id":"i1","texte":"Le haut et le bas, ordre naturel des places"},{"id":"i2","texte":"La position centrale de l’homme"},{"id":"i3","texte":"La nature comme système à mesurer"}]},{"enonce":"Complète la formule d’Alexandre Koyré.","aide":"Elle résume tout le chapitre : l’ancien cosmos d’un côté, le nouveau de l’autre.","type":"trous","segments":["Du monde ",0," à l’univers ",1,"."],"banque":["clos","infini","ouvert","fini"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"Le mot est **vertige** : c’est l’équivalent de l’effroi de Pascal devant l’infini."},{"cle":{"type":"choix","ids":["d"]},"explication":"Pour Pascal, l’homme est un roseau **pensant** : écrasé par l’univers, mais supérieur à lui parce qu’il le sait."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Se perdent la **position centrale** et l’**ordre des places** ; s’établissent la **gravitation universelle** et une nature **mesurable**."},{"cle":{"type":"trous","trous":[["clos"],["infini"]]},"affichage":"clos · infini","explication":"Koyré résume la révolution astronomique : du monde **clos** à l’univers **infini**."}]$ex$::jsonb),
  ('6423cdff-74d4-5d3a-b7fb-7aea47f01607'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La vanité de Yanis","competence":"observer-schema","situation":"Yanis compose une vanité sur son bureau, comme les peintres du XVIIe siècle. Il hésite sur ce qui doit s’y trouver. Aide-le, puis range les traits baroques et classiques.","documents":[{"id":"bureau","type":"schema","titre":"Le bureau de Yanis","largeur":320,"hauteur":200,"elements":[{"forme":"rect","x":15,"y":120,"l":290,"h":28,"teinte":"brun","motif":"clair","arrondi":4},{"forme":"emoji","x":40,"y":108,"emoji":"💀","taille":36,"id":"z1","zone":true},{"forme":"emoji","x":92,"y":108,"emoji":"📱","taille":36,"id":"z2","zone":true},{"forme":"emoji","x":144,"y":108,"emoji":"⏳","taille":36,"id":"z3","zone":true},{"forme":"emoji","x":196,"y":108,"emoji":"🥀","taille":36,"id":"z4","zone":true},{"forme":"emoji","x":248,"y":108,"emoji":"🔑","taille":36,"id":"z5","zone":true},{"forme":"emoji","x":292,"y":108,"emoji":"🫧","taille":36,"id":"z6","zone":true},{"forme":"texte","x":160,"y":180,"texte":"Quels objets disent la brièveté de la vie ?","taille":"petit","ancre":"milieu","italique":true}],"source":"Schéma imaginaire"}],"questions":[{"enonce":"Touche les quatre objets qui rappellent la brièveté de la vie dans une vanité.","aide":"Pense au temps qui passe, à ce qui se fane, à ce qui éclate.","type":"zone","document":"bureau","multiple":true},{"enonce":"Associe chaque motif baroque à ce qu’il rappelle.","aide":"« Memento mori » est une phrase latine : traduis-la.","type":"association","gauche":[{"id":"g0","texte":"Vanité"},{"id":"g1","texte":"Memento mori"},{"id":"g2","texte":"Theatrum mundi"}],"droite":[{"id":"d0","texte":"La brièveté de la vie"},{"id":"d1","texte":"Le monde est un théâtre où chacun joue un rôle"},{"id":"d2","texte":"Souviens-toi que tu vas mourir"}]},{"enonce":"Range chaque trait du côté du baroque ou du classicisme.","aide":"Le classicisme cherche la mesure ; le baroque, le mouvement et l’excès.","type":"categories","categories":[{"id":"c0","texte":"Baroque"},{"id":"c1","texte":"Classicisme"}],"items":[{"id":"i0","texte":"Symétrie et clarté"},{"id":"i1","texte":"Profusion d’ornements"},{"id":"i2","texte":"Respect des règles et unité"},{"id":"i3","texte":"Trompe-l’œil, plafonds ouverts sur le ciel"},{"id":"i4","texte":"Lignes courbes et torsions"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z3","z4","z6"]},"explication":"Le **crâne, le sablier, la fleur fanée et la bulle de savon** sont les signes de la vanité. Le téléphone et la clé n’y ont pas de sens symbolique."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"La **vanité** dit la brièveté de la vie, **memento mori** l’impératif de la mort, **theatrum mundi** le monde comme théâtre."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c0"}},"explication":"**Baroque** : mouvement, illusion, excès. **Classicisme** : mesure, symétrie, clarté, règles et unité."}]$ex$::jsonb),
  ('6423cdff-74d4-5d3a-b7fb-7aea47f01607'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le plafond qui s’ouvre sur le ciel","competence":"analyser-document","situation":"Une guide-conférencière décrit le plafond d’une église imaginaire du XVIIe siècle. Tu repères dans sa description les traits qui font reconnaître un art baroque.","documents":[{"id":"plafond","type":"texte","genre":"article","titre":"Description d’un plafond","blocs":["Au plafond, la voûte semble s’ouvrir sur le ciel : des nuages, des anges, une architecture peinte qui prolonge les vraies colonnes de la nef. L’œil s’y trompe.","Les corps se tordent en diagonales, les drapés s’agitent comme sous le vent. Un coin est plongé dans l’ombre, un autre éclate de lumière : le contraste est violent."],"source":"Description écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que le plafond fait illusion.","aide":"Quel verbe dit que le regard se laisse abuser ?","type":"zone","document":"plafond","multiple":false},{"enonce":"Touche le mot qui renvoie au clair-obscur, cher au Caravage.","aide":"Ombre et lumière opposées avec force : quel adjectif le dit ?","type":"zone","document":"plafond","multiple":false},{"enonce":"Associe chaque trait baroque à sa manifestation.","aide":"Chaque trait a une manifestation visible dans le texte.","type":"association","gauche":[{"id":"g0","texte":"Le mouvement"},{"id":"g1","texte":"L’illusion"},{"id":"g2","texte":"Le contraste"},{"id":"g3","texte":"L’excès"}],"droite":[{"id":"d0","texte":"Trompe-l’œil et plafonds ouverts sur le ciel"},{"id":"d1","texte":"Lignes courbes, torsions, diagonales"},{"id":"d2","texte":"Ombre et lumière violemment opposées"},{"id":"d3","texte":"Profusion des ornements, saturation"}]},{"enonce":"Quelle inquiétude cette mise en scène d’une instabilité traduit-elle ?","aide":"Si l’univers est infini et la Terre en mouvement, que devient la confiance dans les apparences ?","type":"choix","options":[{"id":"a","texte":"Dans un monde sans repères, les apparences peuvent tromper"},{"id":"b","texte":"On cherche surtout à copier exactement la nature observée"},{"id":"c","texte":"On veut retrouver une symétrie apaisée et rassurante"},{"id":"d","texte":"On craint de manquer de couleurs vives pour décorer les églises"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"Le mot est **trompe** : le trompe-l’œil fait disparaître la limite entre l’espace peint et l’espace réel."},{"cle":{"type":"zone","ids":["m59"]},"explication":"Le mot est **violent** : le contraste violent d’ombre et de lumière est la marque du clair-obscur."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"Le **mouvement** (diagonales), l’**illusion** (ciel peint), le **contraste** (clair-obscur) : le plafond les réunit presque tous."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’instabilité baroque est une **réponse** à un monde où plus rien ne tient : si les apparences peuvent tromper, l’art le met en scène."}]$ex$::jsonb),
  ('6423cdff-74d4-5d3a-b7fb-7aea47f01607'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quand le public monte sur scène","competence":"analyser-texte","situation":"Dans cette scène écrite à la manière de L’Illusion comique, les spectateurs sont eux aussi des comédiens. Tu y reconnais le motif du monde comme théâtre et le trait baroque qui le porte à sa forme achevée.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Scène imaginée","blocs":[{"didascalie":"Léandre, en costume de roi, s’adresse à Isabelle."},{"personnage":"Léandre","replique":"Majesté, la couronne que je porte n’est que du carton."},{"personnage":"Isabelle","replique":"Chut ! Nous jouons devant des spectateurs qui jouent eux-mêmes un autre rôle."},{"didascalie":"Au fond, des spectateurs en costume applaudissent : ce sont aussi des comédiens."},{"personnage":"Léandre","replique":"Alors qui joue, et qui regarde ?"}],"source":"Scène écrite pour l’exercice, à la manière de Corneille, *L’Illusion comique*"},{"id":"grille","type":"tableau","titre":"Grille de lecture baroque","colonnes":["Le trait","La question à se poser"],"lignes":[["Mouvement","Rien n’est-il stable ?"],["Illusion","L’art montre-t-il qu’il fait illusion ?"],["Métamorphose","Les êtres changent-ils d’état, se déguisent-ils ?"],["Contraste","L’ombre et la lumière s’opposent-elles ?"],["Excès","Les ornements débordent-ils ?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que le public lui-même joue un rôle.","aide":"Qui, dans la salle, est aussi sur scène ?","type":"zone","document":"scene","multiple":false},{"enonce":"Le théâtre dans le théâtre est la forme achevée d’un trait baroque. Touche-le dans la grille.","aide":"Les personnages se déguisent, changent d’état : quel trait est-ce ?","type":"zone","document":"grille","multiple":false},{"enonce":"Associe chaque œuvre à son auteur.","aide":"Une pièce espagnole, une pièce française, et le grand dramaturge anglais.","type":"association","gauche":[{"id":"g0","texte":"La vie est un songe"},{"id":"g1","texte":"L’Illusion comique"},{"id":"g2","texte":"Le monde comme théâtre"}],"droite":[{"id":"d0","texte":"Corneille"},{"id":"d1","texte":"Calderón"},{"id":"d2","texte":"Shakespeare"}]},{"enonce":"Que suggère la dernière réplique de Léandre ?","aide":"Léandre ne sait plus qui est acteur et qui est public.","type":"choix","options":[{"id":"a","texte":"Que la frontière entre jouer et regarder, scène et monde, s’efface"},{"id":"b","texte":"Que le roi de carton est devenu un véritable souverain"},{"id":"c","texte":"Que les spectateurs doivent quitter la salle immédiatement"},{"id":"d","texte":"Que la pièce doit reprendre depuis le tout début"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25"]},"explication":"Le mot est **spectateurs** : ceux qui regardent sont aussi des comédiens, c’est le théâtre dans le théâtre."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"C’est la **métamorphose** : les êtres changent d’état et se déguisent, et le théâtre dans le théâtre en est la forme achevée."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le motif du **theatrum mundi** traverse **Shakespeare**, **Calderón** (*La vie est un songe*) et **Corneille** (*L’Illusion comique*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"La question de Léandre dit le **theatrum mundi** : si les spectateurs jouent aussi, scène et monde se confondent, et chacun joue un rôle qu’il n’a pas choisi."}]$ex$::jsonb),
  ('a52cf1ab-f525-5cc2-949c-fd29bbabaebf'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les chiffres d’une grande entreprise","competence":"lire-tableau","situation":"Pour ta fiche de lecture, tu relèves les chiffres de l’Encyclopédie de Diderot et d’Alembert, puis tu retrouves comment elle range le savoir.","documents":[{"id":"chiffres","type":"tableau","titre":"L’Encyclopédie en chiffres","colonnes":["Le chiffre","Sa valeur"],"lignes":[["Années de publication","1751 à 1772"],["Volumes","28"],["Dont volumes de planches","11"],["Articles","Plus de 70 000"],["Collaborateurs","Environ 150"]],"enteteLignes":true,"source":"Chiffres du cours"}],"questions":[{"enonce":"Touche la case qui donne la période de publication.","aide":"Cherche une période, pas un nombre isolé.","type":"zone","document":"chiffres","multiple":false},{"enonce":"Combien de volumes ne sont pas des volumes de planches ?","aide":"Retranche les volumes de planches du nombre total de volumes.","type":"nombre","unite":"volumes"},{"enonce":"Associe chaque faculté de l’arbre des connaissances à sa branche du savoir.","aide":"L’ordre du savoir suit les facultés humaines, non la théologie.","type":"association","gauche":[{"id":"g0","texte":"Mémoire"},{"id":"g1","texte":"Raison"},{"id":"g2","texte":"Imagination"}],"droite":[{"id":"d0","texte":"La poésie"},{"id":"d1","texte":"La philosophie"},{"id":"d2","texte":"L’histoire"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"La case est **1751 à 1772** : l’Encyclopédie est publiée pendant plus de vingt ans."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17 volumes","explication":"28 − 11 = **17 volumes** de texte. Les onze volumes de planches montrent les arts mécaniques : le savoir doit être utile et accessible."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"**Mémoire** → histoire, **raison** → philosophie, **imagination** → poésie : l’arbre range le savoir selon les facultés humaines."}]$ex$::jsonb),
  ('a52cf1ab-f525-5cc2-949c-fd29bbabaebf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un article qui en cache un autre","competence":"analyser-document","situation":"Dans une encyclopédie imaginaire, deux articles se répondent. Tu découvres comment les encyclopédistes déjouaient la censure, puis les avantages et les défauts des deux façons de classer le savoir.","documents":[{"id":"articles","type":"texte","genre":"article","titre":"Deux articles imaginés","blocs":["**RESPECT**, subst. masc. Sentiment qu’on doit aux puissances établies. Voyez ÉVIDENCE.","**ÉVIDENCE**, subst. fém. Ce que la raison reconnaît sans avoir besoin d’aucune autorité."],"source":"Articles écrits pour l’exercice, dans l’esprit de l’Encyclopédie"}],"questions":[{"enonce":"Touche le mot qui annonce un renvoi vers un autre article.","aide":"Les articles de dictionnaire emploient un impératif pour envoyer ailleurs.","type":"zone","document":"articles","multiple":false},{"enonce":"À quoi sert ce renvoi dans une œuvre menacée par la censure ?","aide":"Compare ce que dit le premier article et ce que dit le second.","type":"choix","options":[{"id":"a","texte":"À raccourcir l’ouvrage pour économiser du papier"},{"id":"b","texte":"À ruiner discrètement un article d’apparence anodine"},{"id":"c","texte":"À obéir aux demandes des censeurs"},{"id":"d","texte":"À prouver que les deux articles disent la même chose"}],"multiple":false},{"enonce":"Range chaque remarque : concerne-t-elle le classement par matières ou l’ordre alphabétique ?","aide":"Un classement montre les liens mais suppose du savoir ; l’autre est neutre mais découpe.","type":"categories","categories":[{"id":"c0","texte":"Par matières"},{"id":"c1","texte":"Par ordre alphabétique"}],"items":[{"id":"i0","texte":"Il suppose de connaître d’avance les frontières entre disciplines"},{"id":"i1","texte":"Il émiette le savoir"},{"id":"i2","texte":"Il montre les liens entre les savoirs"},{"id":"i3","texte":"Il est consultable par qui ne connaît pas encore les disciplines"}]},{"enonce":"Que devient l’ouvrage après la révocation du privilège, en 1759 ?","aide":"Le dernier volume paraît en 1772.","type":"choix","options":[{"id":"a","texte":"Il est détruit avant la dernière planche"},{"id":"b","texte":"Il est confié au roi qui l’achève"},{"id":"c","texte":"Il se poursuit dans la semi-clandestinité"},{"id":"d","texte":"Il est abandonné définitivement"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"Le mot est **Voyez** : le renvoi mène du premier article au second."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le premier article paraît respectueux ; le second parle d’une raison **sans aucune autorité**. Le **système des renvois** permet de contredire sans le dire."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"Le classement **par matières** montre les liens mais exige de connaître les disciplines ; l’**alphabétique** est neutre mais émiette. L’Encyclopédie choisit l’alphabet **et** l’arbre."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le privilège est révoqué en **1759**, mais l’Encyclopédie continue dans la **semi-clandestinité** jusqu’en 1772."}]$ex$::jsonb),
  ('a52cf1ab-f525-5cc2-949c-fd29bbabaebf'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les angles morts d’une encyclopédie en ligne","competence":"analyser-document","situation":"Une encyclopédie collaborative imaginaire publie le nombre d’articles par continent. Tu croises ce graphique avec les questions que l’on doit poser à toute encyclopédie.","documents":[{"id":"graphe","type":"graphique","forme":"barres","titre":"Articles par continent (en milliers)","categories":["Europe","Amérique du Nord","Asie","Afrique","Océanie"],"series":[{"nom":"Articles","valeurs":[420,310,150,40,25],"teinte":"violet"}],"axeY":{"titre":"Articles","unite":"en milliers","min":0,"max":450,"pas":50},"axeX":{"titre":"Continent"},"valeurs":true,"source":"Données imaginaires, écrites pour l’exercice"},{"id":"grille","type":"tableau","titre":"Quatre questions à poser","colonnes":["La question","Ce qu’elle vise"],"lignes":[["Qui écrit ?","La légitimité"],["Selon quelles règles ?","La méthode"],["Avec quelle vérification ?","La fiabilité"],["Qu’est-ce qui reste absent ?","Les angles morts"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la barre du continent le moins représenté dans cette encyclopédie.","aide":"Cherche la barre la plus basse.","type":"zone","document":"graphe","multiple":false},{"enonce":"Combien d’articles (en milliers) l’Europe et l’Afrique réunies totalisent-elles ?","aide":"Additionne les deux valeurs de ces barres.","type":"nombre","unite":"milliers"},{"enonce":"Touche la question qui permet de repérer que l’Afrique et l’Océanie sont à peine présentes.","aide":"On cherche ce que l’encyclopédie ne dit pas, ou dit à peine.","type":"zone","document":"grille","multiple":false},{"enonce":"Que montre ce graphique de l’entreprise encyclopédique ?","aide":"Classer, c’est déjà interpréter : le choix n’est jamais innocent.","type":"choix","options":[{"id":"a","texte":"Les régions du monde se valent dans une encyclopédie collaborative"},{"id":"b","texte":"Une encyclopédie est neutre dès lors qu’elle est alphabétique"},{"id":"c","texte":"Toute encyclopédie comporte des angles morts, qu’il faut savoir repérer"},{"id":"d","texte":"Classer le savoir est un geste sans conséquence"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"La barre la plus basse est celle de l’**Océanie** : 25 000 articles seulement."},{"cle":{"type":"nombre","valeur":460,"tolerance":0},"affichage":"460 milliers","explication":"420 + 40 = **460 milliers**, soit 460 000 articles : l’Europe pèse dix fois plus que l’Afrique."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"C’est la question **« Qu’est-ce qui reste absent ? »** : elle vise les angles morts, comme les régions du monde traitées à la marge."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le déséquilibre montre un **angle mort** : ce qu’une encyclopédie traite à la marge fait partie de sa lecture. Classer n’est jamais un geste neutre."}]$ex$::jsonb),
  ('1066843a-dec3-5bdd-84aa-277ded557822'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le couloir qui se resserre","competence":"geometrie","situation":"Dans un atelier de Florence, un apprenti trace un couloir en perspective linéaire. Les lignes du sol et du plafond se rejoignent au loin : tu retrouves le principe de la méthode de Brunelleschi.","documents":[{"id":"couloir","type":"figure","cadre":{"xmin":-1,"xmax":13,"ymin":-1,"ymax":9},"quadrillage":false,"points":[{"id":"A","x":0,"y":0,"position":"ne"},{"id":"B","x":12,"y":0,"position":"no"},{"id":"C","x":0,"y":8,"position":"se"},{"id":"D","x":12,"y":8,"position":"so"},{"id":"F","x":6,"y":4,"position":"n"},{"id":"H","x":0,"y":4,"position":"ne"},{"id":"G","x":12,"y":4,"position":"no"}],"segments":[{"de":"A","a":"F","id":"z1"},{"de":"B","a":"F","id":"z2"},{"de":"C","a":"F","id":"z3"},{"de":"D","a":"F","id":"z4"}],"droites":[{"par":["H","G"],"style":"axe","id":"z5"}],"source":"Schéma de construction, sans échelle"}],"questions":[{"enonce":"Touche le point de fuite, où se rejoignent les lignes du sol et du plafond.","aide":"Les quatre lignes obliques se rencontrent en un seul point.","type":"zone","document":"couloir","multiple":false},{"enonce":"Touche la ligne d’horizon, sur laquelle se trouve le point de fuite.","aide":"C’est la ligne horizontale qui passe par le point de fuite.","type":"zone","document":"couloir","multiple":false},{"enonce":"Complète le principe de la perspective linéaire.","aide":"Un cadre qu’on regarde pour voir dehors ; plus c’est loin, plus c’est petit.","type":"trous","segments":["Le tableau est traité comme une ",0," ouverte sur l’espace, et la taille ",1," avec l’éloignement."],"banque":["décroît","grandit","porte","fenêtre"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["F"]},"explication":"Le point **F** est le **point de fuite** : les parallèles perpendiculaires au tableau y convergent."},{"cle":{"type":"zone","ids":["z5"]},"explication":"La **ligne d’horizon** passe par le point de fuite : c’est sur elle que convergent les lignes de fuite."},{"cle":{"type":"trous","trous":[["fenetre"],["decroit","diminue"]]},"affichage":"fenêtre · décroît","explication":"Le tableau est une **fenêtre** ouverte sur l’espace, et la taille des figures **décroît** avec l’éloignement."}]$ex$::jsonb),
  ('1066843a-dec3-5bdd-84aa-277ded557822'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux Annonciations, deux manières de voir","competence":"analyser-document","situation":"Un conservateur compare deux Annonciations imaginaires, l’une du Moyen Âge, l’autre de la Renaissance. Tu lis le tableau comparatif, tu calcules avec la règle de la perspective, puis tu en tires la leçon de Panofsky.","documents":[{"id":"comparaison","type":"tableau","titre":"Deux Annonciations imaginaires","colonnes":["","Image A (vers 1300)","Image B (vers 1450)"],"lignes":[["Taille des figures","La Vierge est immense, l’ange tout petit","La Vierge et l’ange ont une taille voisine, plus petits au fond"],["Espace","Fond doré, sans lieu précis","Salle au carrelage dont les lignes convergent"],["Spectateur","Aucun point de vue précis","Un seul point de vue, devant la salle"],["Étude préparatoire","Aucun calcul","Un homme de 1,80 m, placé à 5 m, mesure 36 mm sur l’étude"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui montre que l’espace de l’image B est cohérent et mesurable.","aide":"Des lignes qui convergent permettent de calculer des distances.","type":"zone","document":"comparaison","multiple":false},{"enonce":"La taille décroît en proportion inverse de la distance. À 10 m, quelle serait la taille de cet homme sur l’étude ?","aide":"La distance double : que devient la taille ?","type":"nombre","unite":"mm"},{"enonce":"Range chaque caractéristique du côté de l’image A ou de l’image B.","aide":"Une image suit l’importance ; l’autre suit la distance.","type":"categories","categories":[{"id":"c0","texte":"Image A"},{"id":"c1","texte":"Image B"}],"items":[{"id":"i0","texte":"La taille dépend de la position"},{"id":"i1","texte":"L’espace est symbolique"},{"id":"i2","texte":"La taille dépend de l’importance"},{"id":"i3","texte":"L’espace est mesurable et cohérent"}]},{"enonce":"Que conclure, avec Panofsky, sur les cultures qui représentent l’espace autrement ?","aide":"Panofsky parle de « forme symbolique ».","type":"choix","options":[{"id":"a","texte":"Elles n’avaient pas encore découvert la vraie manière de voir"},{"id":"b","texte":"Elles étaient moins précises pour des raisons purement techniques et matérielles"},{"id":"c","texte":"Elles n’ont jamais cherché à représenter l’espace"},{"id":"d","texte":"Elles n’ont commis ni erreur ni retard : la perspective est une convention"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"La case est **le carrelage dont les lignes convergent** : l’espace est construit géométriquement, donc cohérent et mesurable."},{"cle":{"type":"nombre","valeur":18,"tolerance":0},"affichage":"18 mm","explication":"À 10 m, soit **deux fois** plus loin qu’à 5 m, il est deux fois plus petit : 36 ÷ 2 = **18 mm**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"L’image **A** (taille selon l’importance, espace symbolique) est médiévale ; l’image **B** (taille selon la position, espace mesurable) suit la perspective."},{"cle":{"type":"choix","ids":["d"]},"explication":"La perspective est une **forme symbolique**, non la vision « vraie » : d’autres cultures ont représenté l’espace autrement, sans erreur ni retard."}]$ex$::jsonb),
  ('1066843a-dec3-5bdd-84aa-277ded557822'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le crâne qu’il faut aller chercher","competence":"analyser-document","situation":"Une fiche de médiation décrit un célèbre tableau de Holbein, *Les Ambassadeurs*. Tu y reconnais un usage détourné de la perspective, puis tu replaces cette remise en cause dans l’histoire de la peinture.","documents":[{"id":"fiche","type":"texte","genre":"article","titre":"Fiche de médiation","blocs":["Dans *Les Ambassadeurs*, de Holbein, une forme allongée traverse le bas du tableau. Vue de face, elle ne ressemble à rien. Il faut se placer sur le côté, presque contre le mur, pour qu’elle se recompose : c’est un crâne.","Le spectateur qui reste devant le tableau ne voit que deux hommes riches et leurs objets. La vanité n’apparaît qu’à qui quitte la place que le tableau lui avait assignée."],"source":"Fiche écrite pour l’exercice, à propos des *Ambassadeurs* de Holbein"},{"id":"remise","type":"tableau","titre":"La remise en cause de la perspective","colonnes":["Le moment","Ce qui advient"],"lignes":[["Cézanne, puis le cubisme","Plusieurs points de vue coexistent sur la même toile"],["La photographie","Elle produit mécaniquement une image perspective et libère la peinture de cette tâche"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit où se placer pour que l’anamorphose se recompose.","aide":"Pas devant le tableau : de quel autre endroit faut-il le regarder ?","type":"zone","document":"fiche","multiple":false},{"enonce":"Associe chaque procédé à son exemple.","aide":"Le premier exemple est dans la fiche ; les autres sont dans le cours.","type":"association","gauche":[{"id":"g0","texte":"L’anamorphose"},{"id":"g1","texte":"Le trompe-l’œil"},{"id":"g2","texte":"Plusieurs points de vue"}],"droite":[{"id":"d0","texte":"Les plafonds baroques"},{"id":"d1","texte":"Le crâne des *Ambassadeurs* de Holbein"},{"id":"d2","texte":"Le cubisme"}]},{"enonce":"Touche la case qui explique pourquoi la peinture n’a plus à imiter la perspective.","aide":"Une machine fait désormais ce travail à sa place.","type":"zone","document":"remise","multiple":false},{"enonce":"Complète la leçon du chapitre.","aide":"Une photographie semble enregistrer ; la peinture, elle, construit.","type":"trous","segments":["Toute représentation est une construction qui choisit un point de vue : représenter n’est jamais ",0,"."],"banque":["enregistrer","colorier","compter","signer"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"Le mot est **côté** : une anamorphose ne se recompose que d’un point oblique."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"L’**anamorphose** (Holbein), le **trompe-l’œil** (plafonds baroques) et le **cubisme** (plusieurs points de vue) jouent de la perspective ou la contestent."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La case est celle de la **photographie** : elle produit mécaniquement une image perspective et libère la peinture de cette tâche."},{"cle":{"type":"trous","trous":[["enregistrer"]]},"affichage":"enregistrer","explication":"Représenter n’est jamais **enregistrer** : choisir un point de vue, c’est en exclure d’autres."}]$ex$::jsonb),
  ('a6b78b07-7484-55a0-a118-dc0db30fb9d9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La silhouette au bout du couloir","competence":"analyser-texte","situation":"Noé rentre tard et croit voir quelqu’un dans l’obscurité. Cette petite histoire te sert de point de départ pour comprendre le procès fait à l’imagination, puis tu relies trois auteurs à leurs formules.","documents":[{"id":"noe","type":"texte","genre":"recit","titre":"Un retour tardif","blocs":["Noé rentre tard. Au bout du couloir sombre, il aperçoit une silhouette immobile. Son cœur s’emballe : il en est sûr, quelqu’un est là.","Il allume la lumière. Ce n’était que son manteau, jeté sur une chaise."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit ce qu’était vraiment la silhouette.","aide":"Il suffit de lire la dernière phrase du récit.","type":"zone","document":"noe","multiple":false},{"enonce":"Quel reproche constant fait-on à l’imagination, que cette scène illustre ?","aide":"Noé était « sûr » de ce qu’il avait imaginé.","type":"choix","options":[{"id":"a","texte":"Elle ne dépend jamais des sensations reçues"},{"id":"b","texte":"Elle empêche tout sentiment de peur ou de doute"},{"id":"c","texte":"Elle refuse absolument de produire des images"},{"id":"d","texte":"Elle confond ce qu’elle produit avec ce qui est"}],"multiple":false},{"enonce":"Associe chaque auteur à sa formule sur l’imagination.","aide":"Deux auteurs la condamnent, un poète du XIXe siècle la célèbre.","type":"association","gauche":[{"id":"g0","texte":"Malebranche"},{"id":"g1","texte":"Pascal"},{"id":"g2","texte":"Baudelaire"}],"droite":[{"id":"d0","texte":"La reine des facultés"},{"id":"d1","texte":"La folle du logis"},{"id":"d2","texte":"Maîtresse d’erreur et de fausseté"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m33"]},"explication":"Le mot est **manteau** : l’imagination avait transformé un vêtement en intrus."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’imagination **confond ce qu’elle produit avec ce qui est** et emporte le jugement par la vivacité de ses images : c’est le reproche constant des classiques."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Malebranche** : « la folle du logis ». **Pascal** : « maîtresse d’erreur et de fausseté ». **Baudelaire** : « la reine des facultés »."}]$ex$::jsonb),
  ('a6b78b07-7484-55a0-a118-dc0db30fb9d9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le radiateur d’Amel","competence":"raisonner","situation":"Amel remarque que son radiateur chauffe mal. Son carnet montre comment on passe d’une idée à une preuve : tu repères le rôle de l’imagination dans la démarche scientifique.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Le carnet d’Amel","blocs":["Mon radiateur chauffe moins vite que prévu. J’imagine que l’eau est mal purgée : c’est une idée, pas encore un fait.","Avant d’en parler à mon père, je mesure la température au bout de dix minutes. Si elle monte beaucoup moins que d’habitude, je garde l’idée ; sinon, je la change."],"source":"Carnet écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui marque le premier temps de la démarche d’Amel.","aide":"Avant de vérifier, que fait-on de sa tête ?","type":"zone","document":"carnet","multiple":false},{"enonce":"Remets dans l’ordre la démarche d’Amel.","aide":"Imaginer est le premier temps ; vérifier est le second.","type":"ordre","items":[{"id":"a","texte":"Elle soumet son idée à l’épreuve des faits"},{"id":"b","texte":"Elle imagine une explication possible"},{"id":"c","texte":"Elle garde, corrige ou abandonne son idée"},{"id":"d","texte":"Elle en tire une conséquence qu’elle peut tester"}]},{"enonce":"Range chaque exemple dans la bonne catégorie de l’imagination scientifique.","aide":"Une catégorie ne demande aucun instrument ; une autre est une fiction utile.","type":"categories","categories":[{"id":"c0","texte":"Hypothèse"},{"id":"c1","texte":"Expérience de pensée"},{"id":"c2","texte":"Modèle"}],"items":[{"id":"i0","texte":"L’ascenseur d’Einstein"},{"id":"i1","texte":"Le dessin d’un atome"},{"id":"i2","texte":"La chute des corps chez Galilée"},{"id":"i3","texte":"Imaginer ce qui pourrait expliquer, avant de le vérifier"}]},{"enonce":"Pourquoi la science ne peut-elle pas se passer d’imagination ?","aide":"Pense au carnet d’Amel : l’idée vient avant la mesure.","type":"choix","options":[{"id":"a","texte":"Parce que l’imagination remplace entièrement les expériences"},{"id":"b","texte":"Parce que les faits ne comptent jamais vraiment en science"},{"id":"c","texte":"Il faut imaginer ce qui pourrait expliquer avant de le vérifier"},{"id":"d","texte":"Parce que la raison est toujours impuissante sans rêverie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"Le mot est **imagine** : l’hypothèse est le premier temps, qui précède toute vérification."},{"cle":{"type":"ordre","ids":["b","d","a","c"]},"explication":"On **imagine**, on **déduit** une conséquence testable, on **vérifie**, puis on **garde ou corrige** l’idée."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c1","i3":"c0"}},"explication":"L’**hypothèse** précède la vérification ; l’**expérience de pensée** (Galilée, Einstein) fait avancer sans instrument ; le **modèle** est une fiction utile."},{"cle":{"type":"choix","ids":["c"]},"explication":"La science n’est pas sans imagination : elle **soumet l’imaginé à l’épreuve** des faits. Imaginer est le premier temps ; vérifier, le second."}]$ex$::jsonb),
  ('a6b78b07-7484-55a0-a118-dc0db30fb9d9'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le procès de l’imagination, en un tableau","competence":"argumenter","situation":"Inès prépare une dissertation : « L’imagination nous éloigne-t-elle du savoir ? » Elle a rangé les auteurs dans un tableau et noté une remarque clé. Tu dégages les arguments, puis tu bâtis son plan.","documents":[{"id":"auteurs","type":"tableau","titre":"Qui dit quoi sur l’imagination","colonnes":["L’auteur","Camp","Sa thèse"],"lignes":[["Malebranche","Procès","« La folle du logis »"],["Pascal","Procès","« Maîtresse d’erreur et de fausseté »"],["Descartes","Procès","Le morceau de cire est connu par l’entendement seul"],["Kant","Réhabilitation","Faculté nécessaire : elle synthétise le divers des sensations"],["Baudelaire","Réhabilitation","« La reine des facultés »"],["Bachelard","Réhabilitation","Elle déforme les images, et c’est là qu’elle crée"]],"enteteLignes":true},{"id":"note","type":"texte","genre":"recit","titre":"La remarque d’Inès","blocs":["Je ne veux pas dire que l’imagination suffit. Ce qui distingue la science de la rêverie, c’est que l’idée imaginée est soumise à l’épreuve des faits."],"source":"Remarque écrite pour l’exercice"}],"questions":[{"enonce":"Touche la case qui donne le rôle que Kant assigne à l’imagination.","aide":"Pour Kant, sans elle, aucune expérience unifiée ne serait possible.","type":"zone","document":"auteurs","multiple":false},{"enonce":"Range chaque argument : joue-t-il contre l’imagination ou pour elle ?","aide":"Les classiques la jugent trompeuse ; Kant et Bachelard y voient une force.","type":"categories","categories":[{"id":"c0","texte":"Contre l’imagination"},{"id":"c1","texte":"Pour l’imagination"}],"items":[{"id":"i0","texte":"Le morceau de cire est connu par l’entendement seul"},{"id":"i1","texte":"Elle emporte le jugement par la vivacité de ses images"},{"id":"i2","texte":"Elle déforme les images, et c’est là qu’elle crée"},{"id":"i3","texte":"Sans elle, aucune expérience unifiée ne serait possible"}]},{"enonce":"Touche le mot qui dit ce qui distingue la science de la rêverie.","aide":"L’idée imaginée doit passer par un test.","type":"zone","document":"note","multiple":false},{"enonce":"Remets dans l’ordre le plan de la dissertation d’Inès.","aide":"On commence par la thèse classique, on la renverse, puis on la dépasse dans la science.","type":"ordre","items":[{"id":"a","texte":"La réhabilitation : elle est nécessaire à la connaissance"},{"id":"b","texte":"Imagination et science : imaginer d’abord, vérifier ensuite"},{"id":"c","texte":"Le procès de l’imagination : elle égare le jugement"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c2"]},"explication":"La case est celle de **Kant** : l’imagination est une faculté nécessaire à la connaissance, qui synthétise le divers des sensations."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"**Contre** : elle trompe le jugement (Pascal), elle est écartée de la méthode (Descartes). **Pour** : elle est nécessaire (Kant), elle crée en déformant (Bachelard)."},{"cle":{"type":"zone","ids":["m27"]},"explication":"Le mot est **épreuve** : la science soumet l’imaginé à l’épreuve des faits, ce que ne fait pas la rêverie."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"Le plan va du **procès** à la **réhabilitation**, puis au point décisif : dans la science, on imagine puis on **vérifie**."}]$ex$::jsonb),
  ('359d22d7-2eb2-58c6-b802-8ff3becfab7d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le propre de l’homme : qui dit quoi ?","competence":"lire-tableau","situation":"Pour l’exposition « Le propre de l’homme », un tableau rassemble les critères avancés depuis l’Antiquité. Tu relies chaque critère à son auteur et à ce qu’il affirme.","documents":[{"id":"criteres","type":"tableau","titre":"Les critères classiques","colonnes":["Le critère","Qui l’avance"],"lignes":[["Le langage","Aristote"],["La technique : fabriquer des outils à fabriquer des outils","Bergson"],["Le rire","Rabelais"],["Un discours nouveau pour une situation nouvelle","Descartes"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case du critère que Bergson avance pour définir l’homme.","aide":"Bergson préfère homo faber à homo sapiens.","type":"zone","document":"criteres","multiple":false},{"enonce":"Associe chaque critère à ce qu’il affirme.","aide":"Aristote parle de logos ; les sépultures disent quelque chose sur la mort.","type":"association","gauche":[{"id":"g0","texte":"Le langage (Aristote)"},{"id":"g1","texte":"La technique (Bergson)"},{"id":"g2","texte":"La culture cumulative"},{"id":"g3","texte":"Les sépultures"}],"droite":[{"id":"d0","texte":"Chaque génération part de l’acquis de la précédente"},{"id":"d1","texte":"Homo faber plutôt que sapiens"},{"id":"d2","texte":"Elles attestent la conscience de la mort"},{"id":"d3","texte":"L’homme dit le juste et l’injuste"}]},{"enonce":"Complète la définition d’Aristote.","aide":"C’est un mot grec qui désigne la parole et la raison.","type":"trous","segments":["L’homme est l’animal doué de ",0,", seul capable de dire le juste et l’injuste."],"banque":["mémoire","rire","outils","logos"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"La case est **la technique** : l’homme fabrique des outils à fabriquer des outils."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Le **logos** dit le juste et l’injuste ; **homo faber** fabrique des outils ; la **culture cumulative** capitalise ; les **sépultures** attestent la conscience de la mort."},{"cle":{"type":"trous","trous":[["logos"]]},"affichage":"logos","explication":"Aristote : l’homme est l’animal doué de **logos**, seul capable de dire le juste et l’injuste."}]$ex$::jsonb),
  ('359d22d7-2eb2-58c6-b802-8ff3becfab7d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ce que les éthologues ont observé","competence":"analyser-document","situation":"Une éthologue présente à sa classe des observations qui ébranlent les critères classiques du propre de l’homme. Tu les confrontes aux critères, puis tu replaces l’homme dans une longue histoire du classement.","documents":[{"id":"obs","type":"tableau","titre":"Des critères mis à l’épreuve","colonnes":["Le critère","Ce qu’on observe ailleurs"],"lignes":[["Les outils","Fabriqués et transmis par des chimpanzés, des corbeaux, des loutres"],["Les cultures locales","Des techniques propres à un groupe, transmises"],["Le langage","Des systèmes structurés ; certains grands singes manient des symboles"],["L’empathie","Coopération, sens de l’équité, formes de deuil"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche le critère, avancé par Bergson, que ces observations contestent d’abord.","aide":"Bergson définit l’homme par ce qu’il fabrique.","type":"zone","document":"obs","multiple":false},{"enonce":"Range chaque trait : l’a-t-on observé ailleurs, ou fait-il partie du faisceau qui reste ?","aide":"Le tableau donne ce qui est partagé ; le cours conclut sur un faisceau.","type":"categories","categories":[{"id":"c0","texte":"Observé aussi chez d’autres animaux"},{"id":"c1","texte":"Fait partie du faisceau qui reste"}],"items":[{"id":"i0","texte":"Fabriquer et transmettre des outils"},{"id":"i1","texte":"Se poser la question du propre de l’homme"},{"id":"i2","texte":"Des formes de deuil et d’équité"},{"id":"i3","texte":"Une culture qui s’accumule sur des milliers de générations"}]},{"enonce":"Que conclut le programme de ces observations ?","aide":"Il ne nie pas toute différence : relis la citation du cours.","type":"choix","options":[{"id":"a","texte":"Il n’y a plus aucune différence entre l’homme et l’animal"},{"id":"b","texte":"Seule la différence de nature est démontrée"},{"id":"c","texte":"La différence est plus vraisemblablement de degré que de nature"},{"id":"d","texte":"Les animaux sont des automates"}],"multiple":false},{"enonce":"Remets dans l’ordre chronologique les étapes du classement de l’homme.","aide":"Du XVIIIe siècle aux recherches les plus récentes.","type":"ordre","items":[{"id":"a","texte":"Darwin l’inscrit dans une continuité évolutive"},{"id":"b","texte":"La paléoanthropologie montre que plusieurs espèces humaines ont coexisté"},{"id":"c","texte":"Linné range l’homme parmi les primates (XVIIIe siècle)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"C’est **les outils** : des chimpanzés, des corbeaux et des loutres en fabriquent et se les transmettent."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"Outils, deuil et équité sont **partagés** ; la culture cumulative sur des milliers de générations et la **question elle-même** font partie du faisceau qui reste."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le programme conclut que la différence est de **degré** plutôt que de **nature**, et que chaque critère disait autant du regard porté que de l’objet regardé."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"**Linné** (XVIIIe siècle), puis **Darwin**, puis la **paléoanthropologie** : l’homme est replacé peu à peu dans le vivant."}]$ex$::jsonb),
  ('359d22d7-2eb2-58c6-b802-8ff3becfab7d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une dispute sur le propre de l’homme","competence":"argumenter","situation":"Emma et Tom se disputent par messages sur ce qui sépare l’homme de l’animal. À toi de repérer les critères en jeu, de mesurer la valeur de chaque objection et de conclure.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Une dispute par messages","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Des corbeaux fabriquent des outils. La technique, ce n’est plus le propre de l’homme."},{"qui":"Tom","texte":"Oui, mais eux ne fabriquent pas d’outils pour fabriquer d’autres outils."},{"qui":"Emma","texte":"Les chimpanzés se transmettent leurs techniques : c’est déjà une culture."},{"qui":"Tom","texte":"Une culture qui s’accumule sur des milliers de générations ?"}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot par lequel Emma nomme la transmission des techniques.","aide":"C’est le mot du cours pour des techniques propres à un groupe.","type":"zone","document":"sms","multiple":false},{"enonce":"À quel auteur la première réplique de Tom renvoie-t-elle ?","aide":"Fabriquer des outils à fabriquer des outils : c’est une formule célèbre.","type":"choix","options":[{"id":"a","texte":"À Bergson, qui préfère homo faber à homo sapiens"},{"id":"b","texte":"À Linné, qui range l’homme parmi les primates"},{"id":"c","texte":"À Aristote, qui définit l’homme par le logos"},{"id":"d","texte":"À Rabelais, qui fait du rire le propre de l’homme"}],"multiple":false},{"enonce":"Range chaque argument : est-il celui d’Emma ou celui de Tom ?","aide":"Emma cite des observations ; Tom cherche ce qui reste propre à l’homme.","type":"categories","categories":[{"id":"c0","texte":"Emma"},{"id":"c1","texte":"Tom"}],"items":[{"id":"i0","texte":"Fabriquer des outils à fabriquer des outils"},{"id":"i1","texte":"Des corbeaux fabriquent des outils"},{"id":"i2","texte":"Une culture cumulative sur des milliers de générations"},{"id":"i3","texte":"Les chimpanzés se transmettent leurs techniques"}]},{"enonce":"Complète la conclusion du chapitre.","aide":"Un ensemble de traits qui se tiennent.","type":"trous","segments":["Le propre de l’homme est peut-être moins un critère unique qu’un ",0,"."],"banque":["secret","danger","outil","faisceau"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m39"]},"explication":"Le mot est **culture** : les chimpanzés se transmettent leurs techniques."},{"cle":{"type":"choix","ids":["a"]},"explication":"Tom reprend **Bergson** : l’homme fabrique des outils *à fabriquer des outils*, ce que ne font pas les corbeaux."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Emma s’appuie sur l’**éthologie** (outils, culture) ; Tom replie le propre de l’homme sur la **technique à plusieurs degrés** et la **culture cumulative**."},{"cle":{"type":"trous","trous":[["faisceau"]]},"affichage":"faisceau","explication":"Le chapitre propose un **faisceau** de traits : langage articulé et syntaxe, culture cumulative, capacité de se représenter des mondes possibles."}]$ex$::jsonb),
  ('0dc3b7c5-b9fb-5fd4-b838-68da30244882'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre voix sur l’animal","competence":"lire-tableau","situation":"Dans ton carnet de philosophie, un tableau rassemble quatre auteurs qui ont pensé l’animal. Tu retrouves celui qui a déplacé le critère moral, puis tu reconstitues l’argument de Descartes.","documents":[{"id":"voix","type":"tableau","titre":"Quatre voix","colonnes":["L’auteur","Ce qu’il dit de l’animal"],"lignes":[["Descartes","Les animaux sont des automates, sans pensée ni sensibilité au sens propre"],["Montaigne","Il se demande si sa chatte ne se joue pas de lui autant que lui d’elle"],["La Fontaine","Il écrit un *Discours à Madame de la Sablière* contre l’animal-machine"],["Bentham","Le critère n’est ni la raison ni la parole, mais la capacité de souffrir"]],"enteteLignes":true,"source":"Résumé du cours"}],"questions":[{"enonce":"Touche l’auteur pour qui le critère moral devient la sensibilité.","aide":"Il remplace « peuvent-ils raisonner ? » par une autre question.","type":"zone","document":"voix","multiple":false},{"enonce":"Remets dans l’ordre l’argument de Descartes sur l’animal-machine.","aide":"On part d’un principe, on constate un fait, on en conclut, puis on en tire la conséquence pratique.","type":"ordre","items":[{"id":"a","texte":"Les animaux n’ont pas de langage"},{"id":"b","texte":"La vivisection ne pose alors aucun problème moral"},{"id":"c","texte":"Ils n’ont donc pas de pensée : ce sont des automates"},{"id":"d","texte":"La pensée est une substance à part, dont le langage est le signe"}]},{"enonce":"Associe chaque auteur à son geste.","aide":"Deux auteurs s’opposent à Descartes par des moyens littéraires ; un troisième change de critère.","type":"association","gauche":[{"id":"g0","texte":"Descartes"},{"id":"g1","texte":"Montaigne"},{"id":"g2","texte":"La Fontaine"},{"id":"g3","texte":"Bentham"}],"droite":[{"id":"d0","texte":"Remplace l’intelligence par la sensibilité"},{"id":"d1","texte":"Renverse la position de surplomb"},{"id":"d2","texte":"Réfute l’animal-machine"},{"id":"d3","texte":"Fait de l’animal un automate"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c0"]},"explication":"C’est **Bentham** : avec lui, le critère moral cesse d’être l’intelligence pour devenir la sensibilité."},{"cle":{"type":"ordre","ids":["d","a","c","b"]},"explication":"Descartes pose que le **langage** est le signe de la pensée, constate que les animaux en sont privés, conclut qu’ils sont des **automates**, d’où la **vivisection**."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"**Descartes** pose l’animal-machine ; **Montaigne**, **La Fontaine** et **Bentham** la contestent chacun à sa manière."}]$ex$::jsonb),
  ('0dc3b7c5-b9fb-5fd4-b838-68da30244882'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Dans le monde d’une tique","competence":"analyser-texte","situation":"Un naturaliste imaginaire décrit le monde d’une tique, l’exemple que von Uexküll a rendu célèbre. Tu reconnais l’idée d’Umwelt et tu l’opposes à la thèse de l’animal-machine.","documents":[{"id":"tique","type":"texte","genre":"article","titre":"La tique sur sa branche","blocs":["Une tique attend sur une branche, immobile, parfois des mois. Elle ne voit rien, n’entend rien : son monde se réduit à quelques signaux.","Quand passe un mammifère, l’odeur de sa sueur la fait lâcher prise ; si elle tombe sur un poil, la chaleur de la peau lui dit où mordre."],"source":"Texte écrit pour l’exercice, d’après l’exemple de la tique de von Uexküll"}],"questions":[{"enonce":"Touche les deux signaux qui composent le monde de la tique.","aide":"Cherche ce que la tique perçoit d’un mammifère qui passe.","type":"zone","document":"tique","multiple":true},{"enonce":"Que veut dire von Uexküll quand il affirme que la tique n’habite pas notre monde ?","aide":"Le cours précise : non parce qu’il lui manque quelque chose.","type":"choix","options":[{"id":"a","texte":"Son monde n’est pas pauvre, il est autrement fait"},{"id":"b","texte":"Elle ne perçoit aucun monde du tout"},{"id":"c","texte":"Il lui manque simplement ce que nous avons"},{"id":"d","texte":"Son monde est le même que le nôtre en plus petit"}],"multiple":false},{"enonce":"Range chaque phrase du côté de l’animal-machine ou de l’Umwelt.","aide":"Une thèse nie toute vie intérieure ; l’autre décrit un monde propre à chaque espèce.","type":"categories","categories":[{"id":"c0","texte":"Animal-machine (Descartes)"},{"id":"c1","texte":"Umwelt (von Uexküll)"}],"items":[{"id":"i0","texte":"Son monde est autrement fait, non plus pauvre"},{"id":"i1","texte":"Ses cris sont comme le grincement d’un ressort"},{"id":"i2","texte":"Il perçoit ce que ses organes et ses besoins découpent"},{"id":"i3","texte":"Il n’a ni pensée ni sensibilité au sens propre"}]},{"enonce":"Complète la phrase sur l’éthologie.","aide":"L’animal se reconnaît dans son reflet.","type":"trous","segments":["Le test du miroir met en évidence, chez certaines espèces, une forme de ",0," de soi."],"banque":["peur","ignorance","langage","reconnaissance"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29","m44"]},"explication":"L’**odeur** et la **chaleur** : le monde perçu de la tique est structuré par ses organes et ses besoins. C’est son **Umwelt**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Chaque espèce vit dans son **Umwelt**, un monde perçu structuré par ses organes et ses besoins : la tique n’est pas privée de monde, elle en habite un autre."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Pour **Descartes**, l’animal est un automate sans sensibilité ; pour **von Uexküll**, chaque espèce a un monde perçu qui lui est propre."},{"cle":{"type":"trous","trous":[["reconnaissance"]]},"affichage":"reconnaissance","explication":"Le test du miroir montre chez certaines espèces une forme de **reconnaissance** de soi."}]$ex$::jsonb),
  ('0dc3b7c5-b9fb-5fd4-b838-68da30244882'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un chien sensible, mais un bien","competence":"argumenter","situation":"Une avocate imaginaire plaide pour un chien maltraité. Elle s’appuie sur le statut de l’animal en droit français, tel qu’il a évolué en 2015. Tu mesures ce que ce compromis dit de la question.","documents":[{"id":"statut","type":"tableau","titre":"Le statut de l’animal en droit français","colonnes":["La période","Le statut"],"lignes":[["Longtemps","Un bien meuble"],["Depuis 2015","Un être vivant doué de sensibilité, tout en restant soumis au régime des biens"]],"enteteLignes":true},{"id":"plaidoirie","type":"texte","genre":"source","titre":"Extrait de plaidoirie imaginaire","blocs":["Madame la Présidente, la loi reconnaît que mon client, un chien, est un être doué de sensibilité. Pourtant, il reste soumis au régime des biens : on peut le vendre ou le donner. La loi a dit qu’il souffre ; elle n’en a pas tiré toutes les conséquences."],"source":"Plaidoirie écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit ce qui, dans le statut de l’animal, n’a pas changé.","aide":"Un animal reste soumis au même régime qu’un objet qu’on possède.","type":"zone","document":"plaidoirie","multiple":false},{"enonce":"Range chaque formule : relève-t-elle de la période d’avant 2015 ou d’après 2015 ?","aide":"La date marque le moment où la sensibilité est reconnue par le droit.","type":"categories","categories":[{"id":"c0","texte":"Avant 2015"},{"id":"c1","texte":"Depuis 2015"}],"items":[{"id":"i0","texte":"Un être vivant doué de sensibilité"},{"id":"i1","texte":"Soumis au régime des biens malgré sa sensibilité"},{"id":"i2","texte":"Traité comme une chose qu’on possède, sans plus"},{"id":"i3","texte":"Un bien meuble"}]},{"enonce":"Que dit ce compromis juridique de l’état de la question ?","aide":"Le cours le résume en une phrase : « la sensibilité est reconnue, les conséquences… ».","type":"choix","options":[{"id":"a","texte":"Les animaux ont désormais les mêmes droits que les humains"},{"id":"b","texte":"Le droit nie encore toute sensibilité animale"},{"id":"c","texte":"La sensibilité est reconnue, mais ses conséquences ne sont pas tirées"},{"id":"d","texte":"La question est définitivement tranchée par la loi"}],"multiple":false},{"enonce":"Complète la leçon de Bentham.","aide":"Sa question : « peuvent-ils souffrir ? »","type":"trous","segments":["Avec Bentham, le critère moral cesse d’être l’intelligence pour devenir la ",0,"."],"banque":["force","propriété","sensibilité","parole"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24"]},"explication":"Le mot est **biens** : depuis 2015, l’animal est sensible, mais le régime des biens continue de s’appliquer."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Avant 2015 : **bien meuble**. Depuis 2015 : **être sensible**, mais toujours soumis au régime des biens."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le compromis dit **exactement où en est la question** : la sensibilité est reconnue, les conséquences ne sont pas tirées."},{"cle":{"type":"trous","trous":[["sensibilite"]]},"affichage":"sensibilité","explication":"Le critère moral devient la **sensibilité** : c’est elle que le droit de 2015 a fini par reconnaître."}]$ex$::jsonb),
  ('717d36b7-96f3-5139-a7d7-43ae984476f4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre manières de penser la justice envers l’animal","competence":"lire-tableau","situation":"Un exposé présente quatre positions sur la place des animaux dans la société. Tu les identifies par leur critère moral et tu retrouves ce que chacune demande.","documents":[{"id":"positions","type":"tableau","titre":"Les positions en présence","colonnes":["La position","Son critère","Ce qu’elle demande"],"lignes":[["Welfarisme","La souffrance","Réduire la souffrance sans contester l’usage"],["Utilitarisme (Peter Singer)","L’intérêt de tout être sensible","Ne pas écarter un intérêt parce qu’il est animal"],["Abolitionnisme (Tom Regan)","Le droit","Mettre fin à l’usage : un « sujet-d’une-vie » n’est pas un moyen"],["Contractualisme","La réciprocité","Pas de droits sans obligations réciproques"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le critère moral de l’abolitionnisme.","aide":"Chez Regan, l’animal est un sujet-d’une-vie : qu’est-ce qu’on lui doit ?","type":"zone","document":"positions","multiple":false},{"enonce":"Associe chaque position à son idée centrale.","aide":"Une seule position accepte l’usage tant qu’il est encadré.","type":"association","gauche":[{"id":"g0","texte":"Welfarisme"},{"id":"g1","texte":"Utilitarisme"},{"id":"g2","texte":"Abolitionnisme"},{"id":"g3","texte":"Contractualisme"}],"droite":[{"id":"d0","texte":"Mettre fin à l’usage des animaux"},{"id":"d1","texte":"Les droits supposent des obligations"},{"id":"d2","texte":"Dénoncer le spécisme"},{"id":"d3","texte":"Élevage, transport et abattage encadrés"}]},{"enonce":"Complète la règle des trois R en expérimentation animale.","aide":"Il s’agit d’améliorer les méthodes pour réduire la souffrance.","type":"trous","segments":["Remplacer, réduire, ",0,"."],"banque":["raffiner","rendre","répéter","rejeter"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le critère de l’abolitionnisme est **le droit** : un animal capable de préférences ne peut être traité comme un moyen."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"Le **welfarisme** encadre, l’**utilitarisme** dénonce le spécisme, l’**abolitionnisme** met fin à l’usage, le **contractualisme** exige la réciprocité."},{"cle":{"type":"trous","trous":[["raffiner"]]},"affichage":"raffiner","explication":"La règle des trois R : **remplacer**, **réduire**, **raffiner**."}]$ex$::jsonb),
  ('717d36b7-96f3-5139-a7d7-43ae984476f4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le débat sur l’élevage intensif","competence":"argumenter","situation":"Au lycée, Camille, Jules et Sam débattent de l’élevage intensif. Chacun défend une position différente : tu identifies leurs critères, puis tu relèves comment l’un répond à l’objection de l’autre.","documents":[{"id":"debat","type":"dialogue","modele":"sms","titre":"Un débat de classe","participants":[{"nom":"Camille","emoji":"👧","cote":"gauche"},{"nom":"Jules","emoji":"👦","cote":"droite"},{"nom":"Sam","emoji":"🧑","cote":"gauche"}],"repliques":[{"qui":"Camille","texte":"On ne peut pas supprimer l’élevage, mais on peut réduire la souffrance : des normes pour l’élevage et l’abattage."},{"qui":"Jules","texte":"Un animal est un sujet-d’une-vie : on n’a pas le droit de s’en servir comme d’un moyen."},{"qui":"Sam","texte":"Des droits supposent des devoirs réciproques. Un animal ne peut en avoir aucun."},{"qui":"Jules","texte":"Alors un bébé n’aurait pas de droits non plus ?"}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui porte l’objection contractualiste de Sam.","aide":"Les droits sont liés à une obligation réciproque : laquelle ?","type":"zone","document":"debat","multiple":false},{"enonce":"Associe chaque personnage au critère moral qu’il retient.","aide":"Camille veut réduire quelque chose ; Jules parle d’un droit ; Sam d’obligations.","type":"association","gauche":[{"id":"g0","texte":"Camille"},{"id":"g1","texte":"Jules"},{"id":"g2","texte":"Sam"}],"droite":[{"id":"d0","texte":"Le droit"},{"id":"d1","texte":"La réciprocité"},{"id":"d2","texte":"La souffrance"}]},{"enonce":"Que vise la dernière réplique de Jules ?","aide":"Un bébé a-t-il des obligations envers les autres ?","type":"choix","options":[{"id":"a","texte":"Défendre l’élevage intensif contre ses détracteurs"},{"id":"b","texte":"Affirmer que les bébés sont de simples animaux comme les autres"},{"id":"c","texte":"Rappeler que de jeunes enfants ont des droits sans devoirs"},{"id":"d","texte":"Montrer que les animaux ont des devoirs envers les humains"}],"multiple":false},{"enonce":"Range chaque argument selon la position qu’il défend.","aide":"Un camp encadre, un autre abolit, le dernier exige de la réciprocité.","type":"categories","categories":[{"id":"c0","texte":"Welfarisme"},{"id":"c1","texte":"Abolitionnisme"},{"id":"c2","texte":"Contractualisme"}],"items":[{"id":"i0","texte":"L’élevage doit rester, mais être encadré"},{"id":"i1","texte":"Il faut mettre fin à l’usage des animaux"},{"id":"i2","texte":"Il faut réduire la souffrance dans les abattoirs"},{"id":"i3","texte":"Un animal ne peut avoir d’obligations, donc pas de droits"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m44"]},"explication":"Le mot est **devoirs** : pour le contractualisme, les droits supposent des obligations réciproques."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Camille** est welfariste (souffrance), **Jules** abolitionniste (droit), **Sam** contractualiste (réciprocité)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Jules répond à l’objection par le cas des **jeunes enfants** et des personnes très vulnérables : titulaires de droits sans devoirs correspondants."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c2"}},"explication":"**Welfarisme** : encadrer l’usage. **Abolitionnisme** : y mettre fin. **Contractualisme** : pas de droits sans réciprocité."}]$ex$::jsonb),
