  ('c2b97941-fbb1-5594-beab-3e565ee245a5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le journal du capteur","competence":"modeliser","situation":"Un capteur de température de maison connectée envoie sa mesure sur un petit serveur. Ce serveur garde l’historique pendant un mois, et la LED d’état du capteur est pilotée par un code couleur en hexadécimal.","documents":[{"id":"j","type":"tableau","titre":"Fonctionnement du capteur","colonnes":["Caractéristique","Valeur"],"lignes":[["Mesures par heure",60],["Taille d’une mesure (octets)",2],["Durée d’archivage (jours)",30],["Taux de compression de l’archive",0.25]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"},{"id":"h","type":"tableau","titre":"Code couleur de la LED","colonnes":["Couleur","Code hexadécimal (rouge, vert, bleu)"],"lignes":[["Orange de la LED d’état","FF 80 00"]],"enteteLignes":true,"source":"Code écrit pour l’exercice"}],"questions":[{"enonce":"Combien d’octets le capteur envoie-t-il en une journée ?","aide":"60 mesures par heure pendant 24 h, de 2 octets chacune.","type":"nombre","unite":"octets"},{"enonce":"Quelle est la taille de l’archive de 30 jours, en ko (1 ko = 1 000 octets) ?","aide":"Multiplie l’octet de la journée par 30, puis divise par 1 000.","type":"nombre","unite":"ko"},{"enonce":"Quelle est la taille de l’archive une fois compressée, en ko ?","aide":"Taux de compression = taille compressée ÷ taille initiale.","type":"nombre","unite":"ko"},{"enonce":"Convertis le code FF 80 00 en décimal : donne les trois valeurs R, V et B.","aide":"FF = 15 × 16 + 15 ; 80 = 8 × 16 ; 00 = 0.","type":"trous","segments":["Rouge : ",0," ; vert : ",1," ; bleu : ",2,"."]},{"enonce":"On archive ces mesures pour les relire exactement plus tard. Quelle compression choisir ?","aide":"Quelle compression restitue tout ?","type":"choix","options":[{"id":"a","texte":"Avec perte (comme jpeg)"},{"id":"b","texte":"Avec perte, car le capteur est précis"},{"id":"c","texte":"Aucune : on supprime les vieilles mesures"},{"id":"d","texte":"Sans perte (comme zip)"}],"multiple":false}]}$ex$::jsonb,
